INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('fa6d5793-4108-43a5-9d40-03dade829bdf', 'profile-1780169301356', 'meltdown', 1780426800000, NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'quick-tap', NULL, 'Meltdown', NULL, NULL, '[]'::jsonb, 1, 1780726168449, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('73fb1bd8-7ef2-474f-adbd-2619744cfccd', 'profile-1780169301356', 'school_incident', 1780513200000, NULL, '[]'::jsonb, 'Robby was taken to the principal''s office', '[]'::jsonb, 'voice', 'Robby got into a fight at school and was taken to the principal''s office. We were given a call by the principal afterwards and had a talk with Robby about the incident when we were having dinner.', NULL, NULL, 'negative', '[]'::jsonb, 1, 1780710228236, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('94b638e3-02d1-4175-9f24-a8e1ac81b786', 'profile-1780169301356', 'helpful', 1780599600000, NULL, '[]'::jsonb, 'Got dressed on his own.', '[]'::jsonb, 'voice', 'Robbie had a good day, he went to school, got dressed on his own, then when he came home he played soccer with dad and built blocks with his brother Andy. He cleaned up his room before going to bed and took his medicine.', NULL, NULL, 'positive', '[]'::jsonb, 1, 1780708957383, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('0c6f9b83-75c4-47f6-8155-cc62f16fdb91', 'profile-1780169301356', 'meltdown', 1780723452298, NULL, '[]'::jsonb, 'Robbie threw a tantrum when mom picked him up from school.', '[]'::jsonb, 'voice', 'Robbie had a rough day. He had a number of different school incidents during and after a field trip. He was misbehaving with his friend, Albie. They purposefully clogged a toilet at the school and then had to apologize to the custodian. When mom picked him up after school, Robbie threw a tantrum and intentionally peed himself, and daddy had to come to school with new clothes so they could leave together and Robbie could get in the car. This made mom really upset and she got a migraine. Robbie was much better in the evening. He ate his dinner, was well behaved around his siblings, and got to watch TV for the last hour or so before bed. He went down rather easily with Andy sleeping in the same room.', NULL, '🌊', 'negative', '[]'::jsonb, 1, 1780723452388, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('68e6be21-1227-4d6a-bd7d-99aba1948de7', 'profile-1780169301356', 'meltdown', 1780807599983, NULL, '[]'::jsonb, 'Threw fire truck during meltdown', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '🌊', 'negative', '[]'::jsonb, 1, 1780807600075, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('e0c48db0-1a64-468e-8949-5b427233ae58', 'profile-1780169301356', 'mom_bonding', 1781071166292, NULL, '[]'::jsonb, 'Went to ice cream social with Mom', '[]'::jsonb, 'voice', 'Robbie had a really good day. He was extremely well behaved in the evening. He read really quietly. He had a decent dinner. He had gone earlier in the day after school to an ice cream social with Mom and had really wanted to play with his friend, Allie, but the two of them have had to be separated recently because they''ve been naughty at times. So Robbie played baseball outside with Dad as a Dad bonding moment and he went to bed in the same room as his brother. He had his medicine before bed. All in all, a very controlled and regulated day.', NULL, '👩', 'positive', '[]'::jsonb, 1, 1781071166379, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('40ec2174-2e5c-4cf2-85d2-1f73cbfe60dc', 'profile-1780169301356', 'playdate', 1781155856600, NULL, '[]'::jsonb, 'Hung out with Karen', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '👫', 'neutral', '[]'::jsonb, 1, 1781155856695, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('e8fddcbb-ef91-42a3-9c6b-6c1cee4abce9', 'profile-1780169301356', 'played_outside', 1781240356304, NULL, '[]'::jsonb, 'Played on the school playground', '[]'::jsonb, 'voice', 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', NULL, '🌳', 'positive', '[]'::jsonb, 1, 1781240356402, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('44f8a170-01a4-41f4-88cf-6959d2f7f8be', 'profile-1780169301356', 'family_adventure', 1781290800000, NULL, '[]'::jsonb, 'Andy’s graduation ceremony at Ella Bailey', '[]'::jsonb, 'quick-tap', NULL, 'Family Adventure', NULL, NULL, '[]'::jsonb, 1, 1781420812521, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('34391eb1-7d18-4306-bbfe-50e457e1001e', 'profile-1780169301356', 'stayed_home', 1781495794604, NULL, '[]'::jsonb, 'Stayed home with babysitter', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '🏠', 'neutral', '[]'::jsonb, 1, 1781495794697, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('87f7ebd3-15e8-44fd-93b8-1475f3268e63', 'profile-1780169301356', 'positive_behavior', 1781636400000, NULL, '[]'::jsonb, 'Was open about his emotions re: Albie with parents', '[]'::jsonb, 'voice', 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', NULL, '🌟', 'positive', '[]'::jsonb, 1, 1781756594993, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('988c3c4b-f246-4f07-a388-96798913c065', 'profile-1780169301356', 'shutdown', 1781756264543, NULL, '[]'::jsonb, 'Shut down and cried at pickup', '[]'::jsonb, 'voice', 'Robbie went to his last day of first grade today. I am unsure how it went during the day, but at pickup he was despondent and unable to attend the end of year party because of his sadness that he was not going to be able to play with Albie. He wanted to go only if he could play with his friend. I told him, unfortunately, that he couldn''t. He began to cry and said, get me out of here. So I took him home. I offered multiple alternatives like different restaurants or activities, but he was in shutdown and very sad. His lips were quivering. And then we ran into his friend, Gus, who is a year older and was with his mom on the front steps. And I said in a panic, Gus, would you like to join us for a play date? And Robbie, I checked with Robbie and Robbie said, okay. And Gus said, okay. So Gus came to our house and Gus played more with me than with Robbie. Robbie tried to engage him, but Robbie was laughing inappropriately and had strange social skills. Robbie peed his pants three times with Gus here, which Gus thought was strange. Gus asked for help with Robbie because Robbie was being weird. Robbie''s feelings were hurt because Gus didn''t pitch a baseball correctly at him. He got angry and hid in his room a couple of times. He was upset because Daisy was physically aggressive with him. And finally, Gus just wanted to leave. And so it was an unsuccessful play date in general, but Robbie was giddy for some of it and laughing, but he just didn''t have very good social skills and it was kind of awkward. Then we ended up having another family over for dinner that had kids and Robbie played very well with the 10-year-old boy, whose name is Thompson. And they played with pranks and Robbie ate a good dinner and was patient about waiting his turn to get on the back of the electrical bike. And even allowed Daisy to sit on his lap for the ride, but he got very tired and wanted to come home and went to bed earlier than normal. And it''s the beginning of summer.', NULL, '🔇', 'negative', '[]'::jsonb, 1, 1781756264644, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6a2bb474-13af-4d44-a1e2-bca54f1419af', 'profile-1780169301356', 'playdate', 1781809200000, NULL, '[]'::jsonb, 'Played with nanny and Andy', '[]'::jsonb, 'voice', 'It was the first official day of summer, Robbie woke up in a good mood and played wonderfully with his nanny, Hyanna, and Andy. He did a choreographed dance with Hyanna that he wanted to show mom. He built an incredibly complex avocado land with Andy involving multiple surfaces and toys and then had Hyanna record a 10 minute video explaining all the creative secret passageways, helicopter pads, etc. of his creation. He also cleaned it up with her help without much prompting. Robbie went across the street to his neighbor''s house and played well with Jasper and Kai and Griffin in his basement with limited expected drama. He was in good spirits and ate well, lots of cookies but also other things, all day.', NULL, '👫', 'positive', '[]'::jsonb, 1, 1781931282733, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('ec0cbd0e-588b-4a10-b716-9ccf439cb4b8', 'profile-1780169301356', 'playdate', 1781930549768, NULL, '[]'::jsonb, 'Did pretend play as a king', '[]'::jsonb, 'voice', 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', NULL, '👫', 'positive', '[]'::jsonb, 1, 1781930549864, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('a2c9c5bd-d104-4198-898c-99d2c71d330c', 'profile-1780169301356', 'poor_transitions', 1782500400000, NULL, '[]'::jsonb, 'Refused to put on shoes', '[]'::jsonb, 'voice', 'Mixed day. Woke up at 2am when Andy was begging for water, and Robbie was unkind to him, then Grouch hit breakfast. He made a lot of noise despite multiple warnings about mops sleeping, but eventually stopped. He refused to put on shoes and was non-compliant, but did get into the car. He was crying softly and holding his stuffed animal avocado. He couldn''t tell me what was wrong, but allowed for a hug. After camp, for reward points, he explained that he was upset earlier because his friend Anthony wouldn''t be at camp. He drew some ideas for the car competition at dinner. He took his medicine and went to bed okay.', NULL, '🎢', 'negative', '[]'::jsonb, 1, 1782792443039, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('2ee06747-ea70-4e48-95ca-b9dc72a4a882', 'profile-1780169301356', 'meltdown', 1782759600000, NULL, '[]'::jsonb, 'Had a meltdown over not getting soda', '[]'::jsonb, 'voice', 'Mixed day. Robbie was okay about getting off to camp, a little bit slow in the morning. Camp went okay as far as I know. Then afterward was really hungry and we went to a Thai place where he had a meltdown over not being allowed a soda. He did get a strawberry milk boba, but didn''t like it. He refused to eat and was crying and screaming in the grocery store for gum and candy. Eventually calmed down at home when we read together on the hammock and he traded in reward points for a prank. Had a good bath and was sweet about sleeping in his sister''s room to keep her feeling safe.', NULL, '🌊', 'negative', '[]'::jsonb, 1, 1782867736827, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('f4c4aa17-bc16-4cf1-aaf4-49192cc171fe', 'profile-1780169301356', 'travel', 1783018800000, NULL, '[]'::jsonb, 'Flew from Aspen, Colorado to Seattle', '[]'::jsonb, 'voice', 'Robbie had a really good day. He woke up early, went to the airport, flew on airplanes, sat by himself, ate normal food, was able to hold his pee, watched a ton of iPad time, but that was okay because it was a travel day. He was pleasant and helpful and had a very good day. Took his medicine, flew from Aspen, Colorado to Seattle.', NULL, '✈️', 'neutral', '[]'::jsonb, 1, 1783139663208, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('acb20488-4031-4904-8652-bc0150c1fba5', 'profile-1780169301356', 'family_adventure', 1783364400000, NULL, '[]'::jsonb, 'Went on an adventure with mom and Andy to Krispy Kreme', '[]'::jsonb, 'voice', 'Robbie had a good day. He was on good behavior, went on an adventure with mom and Andy to Krispy Kreme and played baseball outside with dad. He was well behaved at night and took his medicine.', NULL, '🎡', 'positive', '[]'::jsonb, 1, 1783458254741, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('96d76a7d-ff91-401a-a8f5-80d6e59fa083', 'profile-1780169301356', 'sibling_harmony', 1783796400000, NULL, '[]'::jsonb, 'Was relatively kind to siblings', '[]'::jsonb, 'voice', 'Robbie had a good day on mom''s birthday. He woke up around the same time mom did and gave her a card. He was relatively kind to his siblings and he stayed at home throughout much of the afternoon while mom went out with a friend. Robbie was really patient in the evening when we went on a family outing to the summer festival on Mercer Island to see the fireworks and he stayed up until past ten. He fell asleep in the car on the way home. He took his medicine right before falling asleep.', NULL, '🫂', 'positive', '[]'::jsonb, 1, 1783892095318, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('72958a57-d616-4318-bbe8-676226bf57f9', 'profile-1780169301356', 'swim_lessons', 1784002068317, NULL, '[]'::jsonb, 'Did swim lessons', '[]'::jsonb, 'voice', 'A mixed to good day for Robbie who went to camp. He came back and did swim lessons as well. He was a bit squirrely throughout the day and not really listening to his parents. He was kind to his sister and also kind to Andy, but he wasn''t respecting everyone''s personal space and it was difficult to get him into bed without horseplay. He did take his medicine and was helpful in cleaning dinner to some extent.', NULL, '🏊', 'positive', '[]'::jsonb, 1, 1784002068407, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('db9e42d2-994b-484d-af1d-c968d3abd031', 'profile-1780169301356', 'custom', 1784265613640, NULL, '[]'::jsonb, 'Swimming lessons with Andy', '[]'::jsonb, 'custom', NULL, 'Swimming Lessons', '🏊', 'positive', '[]'::jsonb, 1, 1784265613642, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('4c23fa72-9e75-4be8-9695-0d9e0b605ac6', 'profile-1780169301356', 'watched_tv', 1784401200000, NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'quick-tap', NULL, 'Watched TV', NULL, NULL, '[]'::jsonb, 1, 1784691013605, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('09de5f0c-4649-4dc1-b3e5-98e32738bb49', 'profile-1780169301356', 'camp', 1784487600000, NULL, '[]'::jsonb, 'Joined Andy’s baby camp', '[]'::jsonb, 'voice', 'Mixed day. Robbie did not want to attend camp and instead joined Andy’s baby camp so they could stay together. He complained the entire day (about the pool temperature, the activities, etc) but was helpful when we couldn’t find Andy. We had a chat about why he hates camp so much and about being more positive. He skipped dinner in order to have quiet time in the tent. At some point he sneaked back into the tent to eat candy and hid the wrappers under his bed. ', NULL, '🏕️', 'positive', '[]'::jsonb, 1, 1784691086782, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3b658515-cce0-4ef7-8655-9d7b25319db8', 'profile-1780169301356', 'drew_comics', 1784574000000, NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'quick-tap', NULL, 'Drew Comics', NULL, NULL, '[]'::jsonb, 1, 1784691281780, 0) ON CONFLICT (id) DO NOTHING;
