INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('c6b7ed3f-03d2-4d56-830e-120711087b63', 'profile-1780169301356', 'shutdown', 1780426800000, NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'quick-tap', NULL, 'Shutdown', NULL, NULL, '[]'::jsonb, 2, 1780726170036, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('4661da75-4c33-4224-a9da-e54323b91b4c', 'profile-1780169301356', 'conflict', 1780513200000, NULL, '[]'::jsonb, 'Robby got into a fight at school', '[]'::jsonb, 'voice', 'Robby got into a fight at school and was taken to the principal''s office. We were given a call by the principal afterwards and had a talk with Robby about the incident when we were having dinner.', NULL, NULL, 'negative', '[]'::jsonb, 2, 1780710228235, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('f0864973-bdc6-46aa-b344-8af954ae2e9d', 'profile-1780169301356', 'dad_bonding', 1780599600000, NULL, '[]'::jsonb, 'Played soccer with dad.', '[]'::jsonb, 'voice', 'Robbie had a good day, he went to school, got dressed on his own, then when he came home he played soccer with dad and built blocks with his brother Andy. He cleaned up his room before going to bed and took his medicine.', NULL, NULL, 'positive', '[]'::jsonb, 2, 1780708957384, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6d87375f-990b-4cba-ad8d-d3d553da0450', 'profile-1780169301356', 'toilet_issue', 1780723452298, NULL, '[]'::jsonb, 'Peed himself during the tantrum.', '[]'::jsonb, 'voice', 'Robbie had a rough day. He had a number of different school incidents during and after a field trip. He was misbehaving with his friend, Albie. They purposefully clogged a toilet at the school and then had to apologize to the custodian. When mom picked him up after school, Robbie threw a tantrum and intentionally peed himself, and daddy had to come to school with new clothes so they could leave together and Robbie could get in the car. This made mom really upset and she got a migraine. Robbie was much better in the evening. He ate his dinner, was well behaved around his siblings, and got to watch TV for the last hour or so before bed. He went down rather easily with Andy sleeping in the same room.', NULL, '💧', 'negative', '[]'::jsonb, 2, 1780723452389, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('081a9d87-1ec6-4fa7-9e18-034eb9ddd601', 'profile-1780169301356', 'aggression', 1780807599983, NULL, '[]'::jsonb, 'Hit Andy while leaving the room', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '😠', 'negative', '[]'::jsonb, 2, 1780807600075, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('e79cc692-5bf5-4847-abf3-d06f3857bc6c', 'profile-1780169301356', 'dad_bonding', 1781071166292, NULL, '[]'::jsonb, 'Played baseball outside', '[]'::jsonb, 'voice', 'Robbie had a really good day. He was extremely well behaved in the evening. He read really quietly. He had a decent dinner. He had gone earlier in the day after school to an ice cream social with Mom and had really wanted to play with his friend, Allie, but the two of them have had to be separated recently because they''ve been naughty at times. So Robbie played baseball outside with Dad as a Dad bonding moment and he went to bed in the same room as his brother. He had his medicine before bed. All in all, a very controlled and regulated day.', NULL, '👨', 'positive', '[]'::jsonb, 2, 1781071166377, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('73466f2d-f7a9-4cbe-98c4-e4721e2edd25', 'profile-1780169301356', 'good_dinner', 1781155856600, NULL, '[]'::jsonb, 'Ate a good dinner of steak', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '😋', 'positive', '[]'::jsonb, 2, 1781155856696, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('d70f09d3-b2cc-449e-a131-a8882336e031', 'profile-1780169301356', 'dad_bonding', 1781240356304, NULL, '[]'::jsonb, 'Dad joined Robbie and siblings on playground', '[]'::jsonb, 'voice', 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', NULL, '👨🏻', 'positive', '[]'::jsonb, 2, 1781240356408, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('babffb2b-89de-4d5d-b588-8a5283344ba9', 'profile-1780169301356', 'played_outside', 1781290800000, NULL, '[]'::jsonb, 'Played on the playground', '[]'::jsonb, 'voice', 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', NULL, '🌳', 'neutral', '[]'::jsonb, 2, 1781420804054, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('0e05943a-05f0-4cb2-bee1-84b7c6f8c3f3', 'profile-1780169301356', 'watched_tv', 1781495794604, NULL, '[]'::jsonb, 'Watched TV', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '📺', 'neutral', '[]'::jsonb, 2, 1781495794700, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('a1655f92-a356-4bdd-9a7f-d2d623e1c680', 'profile-1780169301356', 'drew_comics', 1781636400000, NULL, '[]'::jsonb, 'Drew comics after school', '[]'::jsonb, 'voice', 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', NULL, '🦸', 'neutral', '[]'::jsonb, 2, 1781756594986, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('5f71b93d-40ce-4451-b852-976075f1b10b', 'profile-1780169301356', 'playdate', 1781756264543, NULL, '[]'::jsonb, 'Had a playdate with Gus', '[]'::jsonb, 'voice', 'Robbie went to his last day of first grade today. I am unsure how it went during the day, but at pickup he was despondent and unable to attend the end of year party because of his sadness that he was not going to be able to play with Albie. He wanted to go only if he could play with his friend. I told him, unfortunately, that he couldn''t. He began to cry and said, get me out of here. So I took him home. I offered multiple alternatives like different restaurants or activities, but he was in shutdown and very sad. His lips were quivering. And then we ran into his friend, Gus, who is a year older and was with his mom on the front steps. And I said in a panic, Gus, would you like to join us for a play date? And Robbie, I checked with Robbie and Robbie said, okay. And Gus said, okay. So Gus came to our house and Gus played more with me than with Robbie. Robbie tried to engage him, but Robbie was laughing inappropriately and had strange social skills. Robbie peed his pants three times with Gus here, which Gus thought was strange. Gus asked for help with Robbie because Robbie was being weird. Robbie''s feelings were hurt because Gus didn''t pitch a baseball correctly at him. He got angry and hid in his room a couple of times. He was upset because Daisy was physically aggressive with him. And finally, Gus just wanted to leave. And so it was an unsuccessful play date in general, but Robbie was giddy for some of it and laughing, but he just didn''t have very good social skills and it was kind of awkward. Then we ended up having another family over for dinner that had kids and Robbie played very well with the 10-year-old boy, whose name is Thompson. And they played with pranks and Robbie ate a good dinner and was patient about waiting his turn to get on the back of the electrical bike. And even allowed Daisy to sit on his lap for the ride, but he got very tired and wanted to come home and went to bed earlier than normal. And it''s the beginning of summer.', NULL, '👫', 'neutral', '[]'::jsonb, 2, 1781756264646, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('65421343-b1dc-4d33-913d-ae0329153a98', 'profile-1780169301356', 'sibling_harmony', 1781930553560, NULL, '[]'::jsonb, 'Pretended Andy was his butler', '[]'::jsonb, 'quick-tap', NULL, 'Sibling Harmony', NULL, NULL, '[]'::jsonb, 2, 1781930553561, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('75856f16-b4e7-4871-9c0c-c57fac0cefa5', 'profile-1780169301356', 'refusal', 1782759600000, NULL, '[]'::jsonb, 'Refused to eat at the restaurant', '[]'::jsonb, 'voice', 'Mixed day. Robbie was okay about getting off to camp, a little bit slow in the morning. Camp went okay as far as I know. Then afterward was really hungry and we went to a Thai place where he had a meltdown over not being allowed a soda. He did get a strawberry milk boba, but didn''t like it. He refused to eat and was crying and screaming in the grocery store for gum and candy. Eventually calmed down at home when we read together on the hammock and he traded in reward points for a prank. Had a good bath and was sweet about sleeping in his sister''s room to keep her feeling safe.', NULL, '🙅', 'negative', '[]'::jsonb, 2, 1782867736832, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('0016b519-ba99-4a49-a040-830df2f2a4de', 'profile-1780169301356', 'good_breakfast', 1782846000000, NULL, '[]'::jsonb, 'Had a good breakfast', '[]'::jsonb, 'voice', 'Great day. Woke up helpful and had a good breakfast. Good and quiet. In the car to camp. At camp played with two friends and did a big hike. Did not eat much. On drive home from camp entertained siblings the whole way with stories about his day and funny voices. Was a good sport about family outing to Highlands Mountain. Played nicely with and was brave around other kids. Was brave around dogs as well. Was patient with Daisy when she tried to hit him. Playful and silly. Though didn''t listen to mom a few times when she asked for help. Came home and asked for silence because his dry lips hurt. Drew a comic book with mom. Attempted to sleep with Daisy but gave up when she screamed too much. Was persuaded back out of kindness to his sister. Awesome day overall. Banked many points and was okay about not being able to spend them tonight.', NULL, '🍳', 'positive', '[]'::jsonb, 2, 1783138713926, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('2b98a45a-711b-4327-a0bd-1422478fedb5', 'profile-1780169301356', 'watched_tv', 1783018800000, NULL, '[]'::jsonb, 'Watched a ton of iPad time', '[]'::jsonb, 'voice', 'Robbie had a really good day. He woke up early, went to the airport, flew on airplanes, sat by himself, ate normal food, was able to hold his pee, watched a ton of iPad time, but that was okay because it was a travel day. He was pleasant and helpful and had a very good day. Took his medicine, flew from Aspen, Colorado to Seattle.', NULL, '📺', 'neutral', '[]'::jsonb, 2, 1783139663211, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9136a8d2-88cf-4426-9da6-a24483fd422c', 'profile-1780169301356', 'played_outside', 1783364400000, NULL, '[]'::jsonb, 'Played baseball outside with dad', '[]'::jsonb, 'voice', 'Robbie had a good day. He was on good behavior, went on an adventure with mom and Andy to Krispy Kreme and played baseball outside with dad. He was well behaved at night and took his medicine.', NULL, '🌳', 'positive', '[]'::jsonb, 2, 1783458254742, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('51b08214-ee1b-46e1-b273-4ef1b9292ccc', 'profile-1780169301356', 'stayed_home', 1783796400000, NULL, '[]'::jsonb, 'Stayed at home while mom went out', '[]'::jsonb, 'voice', 'Robbie had a good day on mom''s birthday. He woke up around the same time mom did and gave her a card. He was relatively kind to his siblings and he stayed at home throughout much of the afternoon while mom went out with a friend. Robbie was really patient in the evening when we went on a family outing to the summer festival on Mercer Island to see the fireworks and he stayed up until past ten. He fell asleep in the car on the way home. He took his medicine right before falling asleep.', NULL, '🏠', 'neutral', '[]'::jsonb, 2, 1783892095319, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('812c4c55-a9ab-4044-9662-551244b2b093', 'profile-1780169301356', 'naughty', 1784002068317, NULL, '[]'::jsonb, 'Wasn''t respecting personal space', '[]'::jsonb, 'voice', 'A mixed to good day for Robbie who went to camp. He came back and did swim lessons as well. He was a bit squirrely throughout the day and not really listening to his parents. He was kind to his sister and also kind to Andy, but he wasn''t respecting everyone''s personal space and it was difficult to get him into bed without horseplay. He did take his medicine and was helpful in cleaning dinner to some extent.', NULL, '😈', 'negative', '[]'::jsonb, 2, 1784002068408, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('5df6395e-5b5e-4ea5-b11a-d7ec9934f499', 'profile-1780169301356', 'meltdown', 1784401200000, NULL, '[]'::jsonb, 'Had a couple of tantrums', '[]'::jsonb, 'voice', 'Today was a travel day. Robbie was overall pretty good with a couple of tantrums, not meltdowns. He ate mainly snacks and junk food because we were traveling and driving, and he was uninterested in making new friends once we joined the camp. He was pleasant in general and helped Andy with his iPad. He repeatedly said “this is boring” aloud during camp events, which was awkward. ', NULL, '🌊', 'negative', '[]'::jsonb, 2, 1784691000907, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('8cf372ec-1bd3-4111-bb68-d1df5a877a36', 'profile-1780169301356', 'helpful', 1784487600000, NULL, '[]'::jsonb, 'Helped find Andy', '[]'::jsonb, 'voice', 'Mixed day. Robbie did not want to attend camp and instead joined Andy’s baby camp so they could stay together. He complained the entire day (about the pool temperature, the activities, etc) but was helpful when we couldn’t find Andy. We had a chat about why he hates camp so much and about being more positive. He skipped dinner in order to have quiet time in the tent. At some point he sneaked back into the tent to eat candy and hid the wrappers under his bed. ', NULL, '🤝🏻', 'positive', '[]'::jsonb, 2, 1784691086784, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('09cd2040-254a-4a98-8fcd-571bcb807733', 'profile-1780169301356', 'toilet_issue', 1784574000000, NULL, '[]'::jsonb, 'Incident with Andy in the bathrooms', '[]'::jsonb, 'voice', 'Good morning, mixed rest of day. he drew instead of going to camp, cleaned up the wrappers. There was an incident with Andy in the bathrooms but it seems to have been Andy’s fault. After lunch Robbie cried that he couldn’t have a cookie and then refused to do anything but draw in the tent. I forced them to drive to the lake and walk home. They ate ice cream and walked with a general good attitude. Then attended afternoon camp and went swimming with me where Robbie had to be redirected/ corrected repeatedly but was generally sweet. Went to afternoon camp, then a babysitter where he got along with Penny and drew pictures, but apparently only ate churros for dinner. Had to leave disco bingo because it was too loud, which was frustrating because it was a fun camp activity. Ate a hot dog at 9pm and went to bed.', NULL, '🚽', 'negative', '[]'::jsonb, 2, 1784691270323, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('14ffc6a4-3a8b-4d32-8150-55dd30173ef9', 'profile-1780169301356', 'playdate', 1780426800000, NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'quick-tap', NULL, 'Playdate', NULL, NULL, '[]'::jsonb, 3, 1780726192691, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b9ad2761-4f8a-4f8d-9083-55416c10a651', 'profile-1780169301356', 'good_dinner', 1780513200000, NULL, '[]'::jsonb, 'He had a nice dinner of salad and a hot dog.', '[]'::jsonb, 'voice', 'Robbie went to the zoo on a field trip and had a lot of fun. He had a nice dinner of salad and a hot dog and pushed his sister on the swing after dinner. He had his medicine before bed.', NULL, NULL, 'positive', '[]'::jsonb, 3, 1780710076712, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('cc7b6b2d-bcba-47d3-af5f-6428ebd36b49', 'profile-1780169301356', 'sibling_harmony', 1780599600000, NULL, '[]'::jsonb, 'Built blocks with Andy.', '[]'::jsonb, 'voice', 'Robbie had a good day, he went to school, got dressed on his own, then when he came home he played soccer with dad and built blocks with his brother Andy. He cleaned up his room before going to bed and took his medicine.', NULL, NULL, 'positive', '[]'::jsonb, 3, 1780708957385, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('7f337268-e631-48d9-96b3-6d9e54d460cf', 'profile-1780169301356', 'naughty', 1780724351187, NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'quick-tap', NULL, 'Naughty', NULL, NULL, '[]'::jsonb, 3, 1780724351188, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('c0dca9c5-42f2-41ed-95c2-1572515fc0d6', 'profile-1780169301356', 'messy', 1780807599983, NULL, '[]'::jsonb, 'Made a mess in his room', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '🫗', 'negative', '[]'::jsonb, 3, 1780807600076, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b08c1e7c-3d13-4ee4-84c5-4f9a899bb1ec', 'profile-1780169301356', 'good_dinner', 1781071166292, NULL, '[]'::jsonb, 'Had a decent dinner', '[]'::jsonb, 'voice', 'Robbie had a really good day. He was extremely well behaved in the evening. He read really quietly. He had a decent dinner. He had gone earlier in the day after school to an ice cream social with Mom and had really wanted to play with his friend, Allie, but the two of them have had to be separated recently because they''ve been naughty at times. So Robbie played baseball outside with Dad as a Dad bonding moment and he went to bed in the same room as his brother. He had his medicine before bed. All in all, a very controlled and regulated day.', NULL, '😋', 'positive', '[]'::jsonb, 3, 1781071166377, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('0303d1ad-3634-47e6-b71f-3aa90431cb63', 'profile-1780169301356', 'positive_behavior', 1781155856600, NULL, '[]'::jsonb, 'Cleaned up after himself', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '🌟', 'positive', '[]'::jsonb, 3, 1781155856697, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('0782a036-2946-4980-9856-b59a3453bf7e', 'profile-1780169301356', 'good_dinner', 1781240356304, NULL, '[]'::jsonb, 'Chicken balls, nectarines, cauliflower ', '[]'::jsonb, 'voice', 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', NULL, '😋', 'positive', '[]'::jsonb, 3, 1781240356409, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('1253e4d0-1801-4d5d-aec3-01dffaa2a8be', 'profile-1780169301356', 'sugar', 1781290800000, NULL, '[]'::jsonb, 'Had a lot of popsicles', '[]'::jsonb, 'voice', 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', NULL, '🍬', 'neutral', '[]'::jsonb, 3, 1781420804055, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3c9459e7-8d04-41ed-92ed-da277b765b2d', 'profile-1780169301356', 'conflict', 1781495794604, NULL, '[]'::jsonb, 'Had conflict over cleaning', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '⚡', 'negative', '[]'::jsonb, 3, 1781495794701, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9bd8b47b-4811-458d-a0c9-f44028699481', 'profile-1780169301356', 'good_dinner', 1781636400000, NULL, '[]'::jsonb, 'Ate a good dinner', '[]'::jsonb, 'voice', 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', NULL, '😋', 'positive', '[]'::jsonb, 3, 1781756594987, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9b1490c1-b9be-482f-8a7d-0fa238888899', 'profile-1780169301356', 'toilet_issue', 1781756264543, NULL, '[]'::jsonb, 'Peed pants three times during playdate', '[]'::jsonb, 'voice', 'Robbie went to his last day of first grade today. I am unsure how it went during the day, but at pickup he was despondent and unable to attend the end of year party because of his sadness that he was not going to be able to play with Albie. He wanted to go only if he could play with his friend. I told him, unfortunately, that he couldn''t. He began to cry and said, get me out of here. So I took him home. I offered multiple alternatives like different restaurants or activities, but he was in shutdown and very sad. His lips were quivering. And then we ran into his friend, Gus, who is a year older and was with his mom on the front steps. And I said in a panic, Gus, would you like to join us for a play date? And Robbie, I checked with Robbie and Robbie said, okay. And Gus said, okay. So Gus came to our house and Gus played more with me than with Robbie. Robbie tried to engage him, but Robbie was laughing inappropriately and had strange social skills. Robbie peed his pants three times with Gus here, which Gus thought was strange. Gus asked for help with Robbie because Robbie was being weird. Robbie''s feelings were hurt because Gus didn''t pitch a baseball correctly at him. He got angry and hid in his room a couple of times. He was upset because Daisy was physically aggressive with him. And finally, Gus just wanted to leave. And so it was an unsuccessful play date in general, but Robbie was giddy for some of it and laughing, but he just didn''t have very good social skills and it was kind of awkward. Then we ended up having another family over for dinner that had kids and Robbie played very well with the 10-year-old boy, whose name is Thompson. And they played with pranks and Robbie ate a good dinner and was patient about waiting his turn to get on the back of the electrical bike. And even allowed Daisy to sit on his lap for the ride, but he got very tired and wanted to come home and went to bed earlier than normal. And it''s the beginning of summer.', NULL, '🚽', 'negative', '[]'::jsonb, 3, 1781756264646, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('da771f54-d5c1-4553-b79b-68958d6e59ae', 'profile-1780169301356', 'helpful', 1781930549768, NULL, '[]'::jsonb, 'Cleaned up after playing', '[]'::jsonb, 'voice', 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', NULL, '🤝🏻', 'positive', '[]'::jsonb, 3, 1781930549865, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('101c4302-a290-4623-a40a-4e10d8570a78', 'profile-1780169301356', 'overwhelm', 1782500400000, NULL, '[]'::jsonb, 'Cried softly while holding stuffed animal', '[]'::jsonb, 'voice', 'Mixed day. Woke up at 2am when Andy was begging for water, and Robbie was unkind to him, then Grouch hit breakfast. He made a lot of noise despite multiple warnings about mops sleeping, but eventually stopped. He refused to put on shoes and was non-compliant, but did get into the car. He was crying softly and holding his stuffed animal avocado. He couldn''t tell me what was wrong, but allowed for a hug. After camp, for reward points, he explained that he was upset earlier because his friend Anthony wouldn''t be at camp. He drew some ideas for the car competition at dinner. He took his medicine and went to bed okay.', NULL, '😢', 'neutral', '[]'::jsonb, 3, 1782792443045, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('d4740d49-8bca-469d-8ade-b8d4ec5147b7', 'profile-1780169301356', 'meltdown', 1782759600000, NULL, '[]'::jsonb, 'Cried and screamed in the grocery store', '[]'::jsonb, 'voice', 'Mixed day. Robbie was okay about getting off to camp, a little bit slow in the morning. Camp went okay as far as I know. Then afterward was really hungry and we went to a Thai place where he had a meltdown over not being allowed a soda. He did get a strawberry milk boba, but didn''t like it. He refused to eat and was crying and screaming in the grocery store for gum and candy. Eventually calmed down at home when we read together on the hammock and he traded in reward points for a prank. Had a good bath and was sweet about sleeping in his sister''s room to keep her feeling safe.', NULL, '🌊', 'negative', '[]'::jsonb, 3, 1782867736833, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('da6c4b70-2049-4cda-a333-f32bb5f4c9ed', 'profile-1780169301356', 'camp', 1782846000000, NULL, '[]'::jsonb, 'Played with two friends at camp', '[]'::jsonb, 'voice', 'Great day. Woke up helpful and had a good breakfast. Good and quiet. In the car to camp. At camp played with two friends and did a big hike. Did not eat much. On drive home from camp entertained siblings the whole way with stories about his day and funny voices. Was a good sport about family outing to Highlands Mountain. Played nicely with and was brave around other kids. Was brave around dogs as well. Was patient with Daisy when she tried to hit him. Playful and silly. Though didn''t listen to mom a few times when she asked for help. Came home and asked for silence because his dry lips hurt. Drew a comic book with mom. Attempted to sleep with Daisy but gave up when she screamed too much. Was persuaded back out of kindness to his sister. Awesome day overall. Banked many points and was okay about not being able to spend them tonight.', NULL, '🏕️', 'positive', '[]'::jsonb, 3, 1783138713927, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('66bcb2f4-148f-4698-a54c-a573d84116e9', 'profile-1780169301356', 'helpful', 1783018800000, NULL, '[]'::jsonb, 'Was pleasant and helpful', '[]'::jsonb, 'voice', 'Robbie had a really good day. He woke up early, went to the airport, flew on airplanes, sat by himself, ate normal food, was able to hold his pee, watched a ton of iPad time, but that was okay because it was a travel day. He was pleasant and helpful and had a very good day. Took his medicine, flew from Aspen, Colorado to Seattle.', NULL, '🤝🏻', 'positive', '[]'::jsonb, 3, 1783139663211, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6feba5e3-78eb-4143-9389-b73bbba8fcb1', 'profile-1780169301356', 'helpful', 1783364400000, NULL, '[]'::jsonb, 'Well behaved throughout evening ', '[]'::jsonb, 'quick-tap', NULL, 'Helpful', NULL, NULL, '[]'::jsonb, 3, 1783458261212, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('4bbebcba-f4bd-4d4b-85ec-32ef11ad3b7f', 'profile-1780169301356', 'family_adventure', 1783796400000, NULL, '[]'::jsonb, 'Went to summer festival with family', '[]'::jsonb, 'voice', 'Robbie had a good day on mom''s birthday. He woke up around the same time mom did and gave her a card. He was relatively kind to his siblings and he stayed at home throughout much of the afternoon while mom went out with a friend. Robbie was really patient in the evening when we went on a family outing to the summer festival on Mercer Island to see the fireworks and he stayed up until past ten. He fell asleep in the car on the way home. He took his medicine right before falling asleep.', NULL, '🎡', 'positive', '[]'::jsonb, 3, 1783892095320, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b6266949-f598-455e-9173-0203896926ca', 'profile-1780169301356', 'kindness', 1784002068317, NULL, '[]'::jsonb, 'Was kind to sister and Andy', '[]'::jsonb, 'voice', 'A mixed to good day for Robbie who went to camp. He came back and did swim lessons as well. He was a bit squirrely throughout the day and not really listening to his parents. He was kind to his sister and also kind to Andy, but he wasn''t respecting everyone''s personal space and it was difficult to get him into bed without horseplay. He did take his medicine and was helpful in cleaning dinner to some extent.', NULL, '🫶', 'positive', '[]'::jsonb, 3, 1784002068409, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('abb07b69-88a0-4efb-9567-11209d991bb5', 'profile-1780169301356', 'party', 1784264573622, NULL, '[]'::jsonb, 'Celebrated birthday with Jasper and Kai', '[]'::jsonb, 'voice', 'Robbie once again went to bike camp and swimming lessons today. In the late afternoon, he went across the street to the neighbor''s house to celebrate the birthday of his friends Jasper and Kai. He then stayed out of the house to play with friends in the neighborhood. He later came back and played soccer in the backyard with Kai and briefly attempted to sell more comics outside. He was pleasant in the evening and took his medicine. He did have a bathroom event at the very end of the day, however, where he spilled pee on his carpet.', NULL, '🎉', 'positive', '[]'::jsonb, 3, 1784264573721, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('e008b4a9-596e-494f-b17c-42b30ab5179e', 'profile-1780169301356', 'fast_food', 1784401200000, NULL, '[]'::jsonb, 'Ate mainly snacks and junk food', '[]'::jsonb, 'voice', 'Today was a travel day. Robbie was overall pretty good with a couple of tantrums, not meltdowns. He ate mainly snacks and junk food because we were traveling and driving, and he was uninterested in making new friends once we joined the camp. He was pleasant in general and helped Andy with his iPad. He repeatedly said “this is boring” aloud during camp events, which was awkward. ', NULL, '🍟', 'neutral', '[]'::jsonb, 3, 1784691000909, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('bcaaa493-da8a-4ea2-adfa-51c062e0345e', 'profile-1780169301356', 'refusal', 1784487600000, NULL, '[]'::jsonb, 'Refused to attend camp', '[]'::jsonb, 'voice', 'Mixed day. Robbie did not want to attend camp and instead joined Andy’s baby camp so they could stay together. He complained the entire day (about the pool temperature, the activities, etc) but was helpful when we couldn’t find Andy. We had a chat about why he hates camp so much and about being more positive. He skipped dinner in order to have quiet time in the tent. At some point he sneaked back into the tent to eat candy and hid the wrappers under his bed. ', NULL, '🙅', 'negative', '[]'::jsonb, 3, 1784691086785, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3f494d49-f6a4-4420-9af1-b169348208c3', 'profile-1780169301356', 'refusal', 1784574000000, NULL, '[]'::jsonb, 'Refused to do anything but draw in the tent', '[]'::jsonb, 'voice', 'Good morning, mixed rest of day. he drew instead of going to camp, cleaned up the wrappers. There was an incident with Andy in the bathrooms but it seems to have been Andy’s fault. After lunch Robbie cried that he couldn’t have a cookie and then refused to do anything but draw in the tent. I forced them to drive to the lake and walk home. They ate ice cream and walked with a general good attitude. Then attended afternoon camp and went swimming with me where Robbie had to be redirected/ corrected repeatedly but was generally sweet. Went to afternoon camp, then a babysitter where he got along with Penny and drew pictures, but apparently only ate churros for dinner. Had to leave disco bingo because it was too loud, which was frustrating because it was a fun camp activity. Ate a hot dog at 9pm and went to bed.', NULL, '🙅', 'negative', '[]'::jsonb, 3, 1784691270324, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('11c4e5b3-c853-412e-a72c-1ba89d7896cc', 'profile-1780169301356', 'medication', 1780426800000, NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'quick-tap', NULL, 'Medication Given', NULL, NULL, '[]'::jsonb, 4, 1780726179857, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('e17240e7-9110-4605-bb94-7f70d3ab49f5', 'profile-1780169301356', 'sibling_harmony', 1780513200000, NULL, '[]'::jsonb, 'He pushed his sister on the swing after dinner.', '[]'::jsonb, 'voice', 'Robbie went to the zoo on a field trip and had a lot of fun. He had a nice dinner of salad and a hot dog and pushed his sister on the swing after dinner. He had his medicine before bed.', NULL, NULL, 'positive', '[]'::jsonb, 4, 1780710076713, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('7e1aae80-e627-4bd3-ac8d-2df174146eb9', 'profile-1780169301356', 'chores', 1780599600000, NULL, '[]'::jsonb, 'Cleaned his room before going to bed.', '[]'::jsonb, 'voice', 'Robbie had a good day, he went to school, got dressed on his own, then when he came home he played soccer with dad and built blocks with his brother Andy. He cleaned up his room before going to bed and took his medicine.', NULL, NULL, 'positive', '[]'::jsonb, 4, 1780708957385, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b4a958b7-9773-4ae5-b632-a06dcd62925c', 'profile-1780169301356', 'watched_tv', 1780723452298, NULL, '[]'::jsonb, 'Watched Bluey for 1+ hours before bed.', '[]'::jsonb, 'voice', 'Robbie had a rough day. He had a number of different school incidents during and after a field trip. He was misbehaving with his friend, Albie. They purposefully clogged a toilet at the school and then had to apologize to the custodian. When mom picked him up after school, Robbie threw a tantrum and intentionally peed himself, and daddy had to come to school with new clothes so they could leave together and Robbie could get in the car. This made mom really upset and she got a migraine. Robbie was much better in the evening. He ate his dinner, was well behaved around his siblings, and got to watch TV for the last hour or so before bed. He went down rather easily with Andy sleeping in the same room.', NULL, '📺', 'neutral', '[]'::jsonb, 4, 1780723452391, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('8249a577-3df2-457d-8c47-ca1f130402c2', 'profile-1780169301356', 'family_adventure', 1780807599983, NULL, '[]'::jsonb, 'Went shopping for art supplies', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '🏕️', 'positive', '[]'::jsonb, 4, 1780807600077, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('cbbd54d5-5129-4a36-a267-cbb5cb241ebe', 'profile-1780169301356', 'helpful', 1781071187743, NULL, '[]'::jsonb, 'Very well behaved in the evening', '[]'::jsonb, 'quick-tap', NULL, 'Helpful', NULL, NULL, '[]'::jsonb, 4, 1781071187744, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3facfe50-dbeb-457d-88df-d8c296b95237', 'profile-1780169301356', 'sibling_harmony', 1781155856600, NULL, '[]'::jsonb, 'Was mild mannered with siblings', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '🫂', 'positive', '[]'::jsonb, 4, 1781155856698, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('ae733dc4-0a46-4720-a3fd-5556eb6d058a', 'profile-1780169301356', 'helpful', 1781241084483, NULL, '[]'::jsonb, 'Volunteered to take a bath', '[]'::jsonb, 'quick-tap', NULL, 'Helpful', NULL, NULL, '[]'::jsonb, 4, 1781241084486, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('8972e4eb-dc76-48a3-83c9-8f888cdd76bc', 'profile-1780169301356', 'positive_behavior', 1781290800000, NULL, '[]'::jsonb, 'Obediently left when asked', '[]'::jsonb, 'voice', 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', NULL, '🌟', 'positive', '[]'::jsonb, 4, 1781420804056, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('cc6b0d60-6559-432a-a68f-ff4edb2e75e5', 'profile-1780169301356', 'meltdown', 1781495794604, NULL, '[]'::jsonb, 'Had a meltdown', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '🌊', 'negative', '[]'::jsonb, 4, 1781495794701, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('36c44dee-fec5-421d-b8d5-1e8e4b4754cf', 'profile-1780169301356', 'sibling_harmony', 1781636400000, NULL, '[]'::jsonb, 'Played nicely with siblings', '[]'::jsonb, 'voice', 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', NULL, '🫂', 'positive', '[]'::jsonb, 4, 1781756594988, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('94fd561d-c7aa-4a10-b2d0-7ddb3b07b759', 'profile-1780169301356', 'playdate', 1781756264543, NULL, '[]'::jsonb, 'Played well with Sarah’s family', '[]'::jsonb, 'voice', 'Robbie went to his last day of first grade today. I am unsure how it went during the day, but at pickup he was despondent and unable to attend the end of year party because of his sadness that he was not going to be able to play with Albie. He wanted to go only if he could play with his friend. I told him, unfortunately, that he couldn''t. He began to cry and said, get me out of here. So I took him home. I offered multiple alternatives like different restaurants or activities, but he was in shutdown and very sad. His lips were quivering. And then we ran into his friend, Gus, who is a year older and was with his mom on the front steps. And I said in a panic, Gus, would you like to join us for a play date? And Robbie, I checked with Robbie and Robbie said, okay. And Gus said, okay. So Gus came to our house and Gus played more with me than with Robbie. Robbie tried to engage him, but Robbie was laughing inappropriately and had strange social skills. Robbie peed his pants three times with Gus here, which Gus thought was strange. Gus asked for help with Robbie because Robbie was being weird. Robbie''s feelings were hurt because Gus didn''t pitch a baseball correctly at him. He got angry and hid in his room a couple of times. He was upset because Daisy was physically aggressive with him. And finally, Gus just wanted to leave. And so it was an unsuccessful play date in general, but Robbie was giddy for some of it and laughing, but he just didn''t have very good social skills and it was kind of awkward. Then we ended up having another family over for dinner that had kids and Robbie played very well with the 10-year-old boy, whose name is Thompson. And they played with pranks and Robbie ate a good dinner and was patient about waiting his turn to get on the back of the electrical bike. And even allowed Daisy to sit on his lap for the ride, but he got very tired and wanted to come home and went to bed earlier than normal. And it''s the beginning of summer.', NULL, '👫', 'positive', '[]'::jsonb, 4, 1781756264647, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('d5ba5db6-363c-46e7-9197-1e3dd2c22518', 'profile-1780169301356', 'helpful', 1781809200000, NULL, '[]'::jsonb, 'Cleaned up with help', '[]'::jsonb, 'voice', 'It was the first official day of summer, Robbie woke up in a good mood and played wonderfully with his nanny, Hyanna, and Andy. He did a choreographed dance with Hyanna that he wanted to show mom. He built an incredibly complex avocado land with Andy involving multiple surfaces and toys and then had Hyanna record a 10 minute video explaining all the creative secret passageways, helicopter pads, etc. of his creation. He also cleaned it up with her help without much prompting. Robbie went across the street to his neighbor''s house and played well with Jasper and Kai and Griffin in his basement with limited expected drama. He was in good spirits and ate well, lots of cookies but also other things, all day.', NULL, '🤝🏻', 'positive', '[]'::jsonb, 4, 1781931282736, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('19411388-91f6-43c2-abe2-fa452856479d', 'profile-1780169301356', 'family_adventure', 1781930549768, NULL, '[]'::jsonb, 'Went on a family adventure to Discovery Park', '[]'::jsonb, 'voice', 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', NULL, '🏕️', 'positive', '[]'::jsonb, 4, 1781930549866, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9cce4528-b4c7-4a1f-86a4-0cc9ca6f5a96', 'profile-1780169301356', 'camp', 1782500400000, NULL, '[]'::jsonb, 'Explained upset about friend not at camp', '[]'::jsonb, 'voice', 'Mixed day. Woke up at 2am when Andy was begging for water, and Robbie was unkind to him, then Grouch hit breakfast. He made a lot of noise despite multiple warnings about mops sleeping, but eventually stopped. He refused to put on shoes and was non-compliant, but did get into the car. He was crying softly and holding his stuffed animal avocado. He couldn''t tell me what was wrong, but allowed for a hug. After camp, for reward points, he explained that he was upset earlier because his friend Anthony wouldn''t be at camp. He drew some ideas for the car competition at dinner. He took his medicine and went to bed okay.', NULL, '🏕️', 'positive', '[]'::jsonb, 4, 1782792443046, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('5eb1df76-6683-4e4d-847b-a6a2bd749104', 'profile-1780169301356', 'bounceback', 1782759600000, NULL, '[]'::jsonb, 'Calmed down at home while reading', '[]'::jsonb, 'voice', 'Mixed day. Robbie was okay about getting off to camp, a little bit slow in the morning. Camp went okay as far as I know. Then afterward was really hungry and we went to a Thai place where he had a meltdown over not being allowed a soda. He did get a strawberry milk boba, but didn''t like it. He refused to eat and was crying and screaming in the grocery store for gum and candy. Eventually calmed down at home when we read together on the hammock and he traded in reward points for a prank. Had a good bath and was sweet about sleeping in his sister''s room to keep her feeling safe.', NULL, '🐦‍🔥', 'positive', '[]'::jsonb, 4, 1782867736834, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('708de49c-072f-4ca7-bc70-9e23cf008f42', 'profile-1780169301356', 'custom', 1782846000000, NULL, '[]'::jsonb, 'Did a big hike at camp', '[]'::jsonb, 'voice', 'Great day. Woke up helpful and had a good breakfast. Good and quiet. In the car to camp. At camp played with two friends and did a big hike. Did not eat much. On drive home from camp entertained siblings the whole way with stories about his day and funny voices. Was a good sport about family outing to Highlands Mountain. Played nicely with and was brave around other kids. Was brave around dogs as well. Was patient with Daisy when she tried to hit him. Playful and silly. Though didn''t listen to mom a few times when she asked for help. Came home and asked for silence because his dry lips hurt. Drew a comic book with mom. Attempted to sleep with Daisy but gave up when she screamed too much. Was persuaded back out of kindness to his sister. Awesome day overall. Banked many points and was okay about not being able to spend them tonight.', 'Hike', '🏕️', 'positive', '[]'::jsonb, 4, 1783138713929, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('676ddfeb-e0bd-4823-b0c5-8c437bd20851', 'profile-1780169301356', 'medication', 1783018800000, NULL, '[]'::jsonb, 'Took his medicine', '[]'::jsonb, 'voice', 'Robbie had a really good day. He woke up early, went to the airport, flew on airplanes, sat by himself, ate normal food, was able to hold his pee, watched a ton of iPad time, but that was okay because it was a travel day. He was pleasant and helpful and had a very good day. Took his medicine, flew from Aspen, Colorado to Seattle.', NULL, '💊', 'neutral', '[]'::jsonb, 4, 1783139663210, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('c2d17e78-f149-4446-ab8f-98219d84874c', 'profile-1780169301356', 'medication', 1783364400000, NULL, '[]'::jsonb, 'Took his medicine', '[]'::jsonb, 'voice', 'Robbie had a good day. He was on good behavior, went on an adventure with mom and Andy to Krispy Kreme and played baseball outside with dad. He was well behaved at night and took his medicine.', NULL, '💊', 'neutral', '[]'::jsonb, 4, 1783458254744, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('89851f9b-4e29-4921-964e-2ac03349523d', 'profile-1780169301356', 'playdate', 1783796400000, NULL, '[]'::jsonb, 'Made friends while playing on playground ', '[]'::jsonb, 'quick-tap', NULL, 'Playdate', NULL, NULL, '[]'::jsonb, 4, 1783892098746, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('cdb9b43b-c670-4c9d-9842-5e1b9b7711f1', 'profile-1780169301356', 'helpful', 1784002068317, NULL, '[]'::jsonb, 'Was helpful in cleaning dinner', '[]'::jsonb, 'voice', 'A mixed to good day for Robbie who went to camp. He came back and did swim lessons as well. He was a bit squirrely throughout the day and not really listening to his parents. He was kind to his sister and also kind to Andy, but he wasn''t respecting everyone''s personal space and it was difficult to get him into bed without horseplay. He did take his medicine and was helpful in cleaning dinner to some extent.', NULL, '🤝🏻', 'positive', '[]'::jsonb, 4, 1784002068411, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('2538fb0b-2e06-4e0c-9c9c-7e8c8c6fb759', 'profile-1780169301356', 'playdate', 1784264573622, NULL, '[]'::jsonb, 'Played with friends in the neighborhood', '[]'::jsonb, 'voice', 'Robbie once again went to bike camp and swimming lessons today. In the late afternoon, he went across the street to the neighbor''s house to celebrate the birthday of his friends Jasper and Kai. He then stayed out of the house to play with friends in the neighborhood. He later came back and played soccer in the backyard with Kai and briefly attempted to sell more comics outside. He was pleasant in the evening and took his medicine. He did have a bathroom event at the very end of the day, however, where he spilled pee on his carpet.', NULL, '👫', 'positive', '[]'::jsonb, 4, 1784264573722, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('d1c296c6-9bd5-4716-a41f-d85f6679b5d5', 'profile-1780169301356', 'camp', 1784401200000, NULL, '[]'::jsonb, 'Said ''this is boring'' during camp events', '[]'::jsonb, 'voice', 'Today was a travel day. Robbie was overall pretty good with a couple of tantrums, not meltdowns. He ate mainly snacks and junk food because we were traveling and driving, and he was uninterested in making new friends once we joined the camp. He was pleasant in general and helped Andy with his iPad. He repeatedly said “this is boring” aloud during camp events, which was awkward. ', NULL, '🏕️', 'neutral', '[]'::jsonb, 4, 1784691000911, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('02824b87-93c7-4172-bf17-9e5cdd37e0cb', 'profile-1780169301356', 'mom_bonding', 1784487600000, NULL, '[]'::jsonb, 'Talked about why he dislikes camp', '[]'::jsonb, 'quick-tap', NULL, 'Mom Bonding', NULL, NULL, '[]'::jsonb, 4, 1784691167713, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('985e906c-34c6-4d65-a42a-420957e94601', 'profile-1780169301356', 'family_adventure', 1784574000000, NULL, '[]'::jsonb, 'Ate ice cream and walked home', '[]'::jsonb, 'voice', 'Good morning, mixed rest of day. he drew instead of going to camp, cleaned up the wrappers. There was an incident with Andy in the bathrooms but it seems to have been Andy’s fault. After lunch Robbie cried that he couldn’t have a cookie and then refused to do anything but draw in the tent. I forced them to drive to the lake and walk home. They ate ice cream and walked with a general good attitude. Then attended afternoon camp and went swimming with me where Robbie had to be redirected/ corrected repeatedly but was generally sweet. Went to afternoon camp, then a babysitter where he got along with Penny and drew pictures, but apparently only ate churros for dinner. Had to leave disco bingo because it was too loud, which was frustrating because it was a fun camp activity. Ate a hot dog at 9pm and went to bed.', NULL, '🍦', 'positive', '[]'::jsonb, 4, 1784691270325, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('69cb1e1f-c2ce-4a6f-b3fa-9db1a38af044', 'profile-1780169301356', 'wet_bed', 1780426800000, NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'quick-tap', NULL, 'Wet Bed', NULL, NULL, '[]'::jsonb, 5, 1780726182997, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('ddf9ccf4-9131-49da-9d7b-346dbf40cc75', 'profile-1780169301356', 'medication', 1780513200000, NULL, '[]'::jsonb, 'He had his medicine before bed.', '[]'::jsonb, 'voice', 'Robbie went to the zoo on a field trip and had a lot of fun. He had a nice dinner of salad and a hot dog and pushed his sister on the swing after dinner. He had his medicine before bed.', NULL, NULL, 'neutral', '[]'::jsonb, 5, 1780710076714, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6db05e27-743b-4fde-a0ea-9d2cd0c58715', 'profile-1780169301356', 'medication', 1780599600000, NULL, '[]'::jsonb, '2mg guanfacine', '[]'::jsonb, 'voice', 'Robbie had a good day, he went to school, got dressed on his own, then when he came home he played soccer with dad and built blocks with his brother Andy. He cleaned up his room before going to bed and took his medicine.', NULL, NULL, 'neutral', '[]'::jsonb, 5, 1780708957386, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('80e89b9e-e11c-4655-b411-41d942537742', 'profile-1780169301356', 'good_sleep', 1780723452298, NULL, '[]'::jsonb, 'Went down easily to sleep with Andy in the same room.', '[]'::jsonb, 'voice', 'Robbie had a rough day. He had a number of different school incidents during and after a field trip. He was misbehaving with his friend, Albie. They purposefully clogged a toilet at the school and then had to apologize to the custodian. When mom picked him up after school, Robbie threw a tantrum and intentionally peed himself, and daddy had to come to school with new clothes so they could leave together and Robbie could get in the car. This made mom really upset and she got a migraine. Robbie was much better in the evening. He ate his dinner, was well behaved around his siblings, and got to watch TV for the last hour or so before bed. He went down rather easily with Andy sleeping in the same room.', NULL, '😴', 'positive', '[]'::jsonb, 5, 1780723452392, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('5547fcc8-8b60-4221-a92f-3a046bd3945d', 'profile-1780169301356', 'bad_language', 1780807599983, NULL, '[]'::jsonb, 'Used potty language at dinner', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '🤬', 'negative', '[]'::jsonb, 5, 1780807600078, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('f8d9f167-3e48-49f2-848c-b59bedd63e63', 'profile-1780169301356', 'medication', 1781071166292, NULL, '[]'::jsonb, 'Had medicine before bed', '[]'::jsonb, 'voice', 'Robbie had a really good day. He was extremely well behaved in the evening. He read really quietly. He had a decent dinner. He had gone earlier in the day after school to an ice cream social with Mom and had really wanted to play with his friend, Allie, but the two of them have had to be separated recently because they''ve been naughty at times. So Robbie played baseball outside with Dad as a Dad bonding moment and he went to bed in the same room as his brother. He had his medicine before bed. All in all, a very controlled and regulated day.', NULL, 'neutral', 'neutral', '[]'::jsonb, 5, 1781071166378, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('4dd17d9b-2c10-4bee-89fd-71562f0c30af', 'profile-1780169301356', 'watched_tv', 1781155856600, NULL, '[]'::jsonb, 'Earned TV time in the evening', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '📺', 'neutral', '[]'::jsonb, 5, 1781155856699, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9b83bcd9-daeb-43ee-ad36-beab92b17b10', 'profile-1780169301356', 'watched_tv', 1781240356304, NULL, '[]'::jsonb, 'Watched TV after dinner', '[]'::jsonb, 'voice', 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', NULL, '📺', 'neutral', '[]'::jsonb, 5, 1781240356411, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('62198226-855e-45a9-9d30-17ae3ff85194', 'profile-1780169301356', 'drew_comics', 1781290800000, NULL, '[]'::jsonb, 'Drew comics at home', '[]'::jsonb, 'voice', 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', NULL, '🦸', 'neutral', '[]'::jsonb, 5, 1781420804057, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('33f06b93-a37a-48d7-83d4-b44117114545', 'profile-1780169301356', 'shutdown', 1781495794604, NULL, '[]'::jsonb, 'Shut down in room', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '🔇', 'negative', '[]'::jsonb, 5, 1781495794702, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('c4f9b3c8-0571-45aa-afd7-660d93c5ded8', 'profile-1780169301356', 'custom', 1781636400000, NULL, '[]'::jsonb, 'Made an impressive block structure with his matchbox cars', '[]'::jsonb, 'custom', NULL, 'Creativity', '🚗', 'positive', '[]'::jsonb, 5, 1781756656722, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('fd9832bd-cb72-414c-afb1-350de95bb5be', 'profile-1780169301356', 'good_dinner', 1781756264543, NULL, '[]'::jsonb, 'Ate a good dinner', '[]'::jsonb, 'voice', 'Robbie went to his last day of first grade today. I am unsure how it went during the day, but at pickup he was despondent and unable to attend the end of year party because of his sadness that he was not going to be able to play with Albie. He wanted to go only if he could play with his friend. I told him, unfortunately, that he couldn''t. He began to cry and said, get me out of here. So I took him home. I offered multiple alternatives like different restaurants or activities, but he was in shutdown and very sad. His lips were quivering. And then we ran into his friend, Gus, who is a year older and was with his mom on the front steps. And I said in a panic, Gus, would you like to join us for a play date? And Robbie, I checked with Robbie and Robbie said, okay. And Gus said, okay. So Gus came to our house and Gus played more with me than with Robbie. Robbie tried to engage him, but Robbie was laughing inappropriately and had strange social skills. Robbie peed his pants three times with Gus here, which Gus thought was strange. Gus asked for help with Robbie because Robbie was being weird. Robbie''s feelings were hurt because Gus didn''t pitch a baseball correctly at him. He got angry and hid in his room a couple of times. He was upset because Daisy was physically aggressive with him. And finally, Gus just wanted to leave. And so it was an unsuccessful play date in general, but Robbie was giddy for some of it and laughing, but he just didn''t have very good social skills and it was kind of awkward. Then we ended up having another family over for dinner that had kids and Robbie played very well with the 10-year-old boy, whose name is Thompson. And they played with pranks and Robbie ate a good dinner and was patient about waiting his turn to get on the back of the electrical bike. And even allowed Daisy to sit on his lap for the ride, but he got very tired and wanted to come home and went to bed earlier than normal. And it''s the beginning of summer.', NULL, '😋', 'positive', '[]'::jsonb, 5, 1781756264648, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('8caa862b-6725-47cc-8a1b-4ae23b2b1e73', 'profile-1780169301356', 'playdate', 1781809200000, NULL, '[]'::jsonb, 'Played with neighbors in basement', '[]'::jsonb, 'voice', 'It was the first official day of summer, Robbie woke up in a good mood and played wonderfully with his nanny, Hyanna, and Andy. He did a choreographed dance with Hyanna that he wanted to show mom. He built an incredibly complex avocado land with Andy involving multiple surfaces and toys and then had Hyanna record a 10 minute video explaining all the creative secret passageways, helicopter pads, etc. of his creation. He also cleaned it up with her help without much prompting. Robbie went across the street to his neighbor''s house and played well with Jasper and Kai and Griffin in his basement with limited expected drama. He was in good spirits and ate well, lots of cookies but also other things, all day.', NULL, '👫', 'positive', '[]'::jsonb, 5, 1781931282737, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('ee79b6f5-f4fa-4b03-84af-be9118479d46', 'profile-1780169301356', 'fast_food', 1781930549768, NULL, '[]'::jsonb, 'Ate fast food at Wendy''s', '[]'::jsonb, 'voice', 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', NULL, '🍟', 'neutral', '[]'::jsonb, 5, 1781930549867, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('d1cfa9ff-0e97-495f-ab65-27c3fd52099d', 'profile-1780169301356', 'drew_comics', 1782500400000, NULL, '[]'::jsonb, 'Drew ideas for car competition at dinner', '[]'::jsonb, 'voice', 'Mixed day. Woke up at 2am when Andy was begging for water, and Robbie was unkind to him, then Grouch hit breakfast. He made a lot of noise despite multiple warnings about mops sleeping, but eventually stopped. He refused to put on shoes and was non-compliant, but did get into the car. He was crying softly and holding his stuffed animal avocado. He couldn''t tell me what was wrong, but allowed for a hug. After camp, for reward points, he explained that he was upset earlier because his friend Anthony wouldn''t be at camp. He drew some ideas for the car competition at dinner. He took his medicine and went to bed okay.', NULL, '🦸', 'positive', '[]'::jsonb, 5, 1782792443047, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('f78e5c0a-8b50-4f58-8034-b497322d6480', 'profile-1780169301356', 'good_sleep', 1782759600000, NULL, '[]'::jsonb, 'Was sweet about sleeping in sister''s room', '[]'::jsonb, 'voice', 'Mixed day. Robbie was okay about getting off to camp, a little bit slow in the morning. Camp went okay as far as I know. Then afterward was really hungry and we went to a Thai place where he had a meltdown over not being allowed a soda. He did get a strawberry milk boba, but didn''t like it. He refused to eat and was crying and screaming in the grocery store for gum and candy. Eventually calmed down at home when we read together on the hammock and he traded in reward points for a prank. Had a good bath and was sweet about sleeping in his sister''s room to keep her feeling safe.', NULL, '😴', 'positive', '[]'::jsonb, 5, 1782867736835, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('fba0161a-796f-40a3-9d1c-55061187f674', 'profile-1780169301356', 'good_sleep', 1783796400000, NULL, '[]'::jsonb, 'Fell asleep in the car after outing', '[]'::jsonb, 'voice', 'Robbie had a good day on mom''s birthday. He woke up around the same time mom did and gave her a card. He was relatively kind to his siblings and he stayed at home throughout much of the afternoon while mom went out with a friend. Robbie was really patient in the evening when we went on a family outing to the summer festival on Mercer Island to see the fireworks and he stayed up until past ten. He fell asleep in the car on the way home. He took his medicine right before falling asleep.', NULL, '😴', 'positive', '[]'::jsonb, 5, 1783892095321, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('7c49bf7d-1229-45aa-a5bf-93352e257291', 'profile-1780169301356', 'poor_transitions', 1784002068317, NULL, '[]'::jsonb, 'Difficult to get into bed without horseplay', '[]'::jsonb, 'voice', 'A mixed to good day for Robbie who went to camp. He came back and did swim lessons as well. He was a bit squirrely throughout the day and not really listening to his parents. He was kind to his sister and also kind to Andy, but he wasn''t respecting everyone''s personal space and it was difficult to get him into bed without horseplay. He did take his medicine and was helpful in cleaning dinner to some extent.', NULL, '🎢', 'negative', '[]'::jsonb, 5, 1784002068410, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('42a1ea63-a773-4581-8d43-932885542674', 'profile-1780169301356', 'sports', 1784264573622, NULL, '[]'::jsonb, 'Played soccer with Kai in the backyard', '[]'::jsonb, 'voice', 'Robbie once again went to bike camp and swimming lessons today. In the late afternoon, he went across the street to the neighbor''s house to celebrate the birthday of his friends Jasper and Kai. He then stayed out of the house to play with friends in the neighborhood. He later came back and played soccer in the backyard with Kai and briefly attempted to sell more comics outside. He was pleasant in the evening and took his medicine. He did have a bathroom event at the very end of the day, however, where he spilled pee on his carpet.', NULL, '⚽', 'positive', '[]'::jsonb, 5, 1784264573724, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('c3a6ddc5-a2b9-45ec-9cba-066cc38477cf', 'profile-1780169301356', 'helpful', 1784401200000, NULL, '[]'::jsonb, 'Helped Andy with his iPad', '[]'::jsonb, 'voice', 'Today was a travel day. Robbie was overall pretty good with a couple of tantrums, not meltdowns. He ate mainly snacks and junk food because we were traveling and driving, and he was uninterested in making new friends once we joined the camp. He was pleasant in general and helped Andy with his iPad. He repeatedly said “this is boring” aloud during camp events, which was awkward. ', NULL, '🤝🏻', 'positive', '[]'::jsonb, 5, 1784691000912, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('886d6a8f-719d-4014-a67b-9b09760412f9', 'profile-1780169301356', 'didnt_eat_dinner', 1784487600000, NULL, '[]'::jsonb, 'Skipped dinner for quiet time', '[]'::jsonb, 'voice', 'Mixed day. Robbie did not want to attend camp and instead joined Andy’s baby camp so they could stay together. He complained the entire day (about the pool temperature, the activities, etc) but was helpful when we couldn’t find Andy. We had a chat about why he hates camp so much and about being more positive. He skipped dinner in order to have quiet time in the tent. At some point he sneaked back into the tent to eat candy and hid the wrappers under his bed. ', NULL, '🍽️', 'negative', '[]'::jsonb, 5, 1784691086786, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('2b67ef4c-ddea-4888-9ee4-7d262e3737fe', 'profile-1780169301356', 'sports', 1784574000000, NULL, '[]'::jsonb, 'Went swimming with Mom', '[]'::jsonb, 'voice', 'Good morning, mixed rest of day. he drew instead of going to camp, cleaned up the wrappers. There was an incident with Andy in the bathrooms but it seems to have been Andy’s fault. After lunch Robbie cried that he couldn’t have a cookie and then refused to do anything but draw in the tent. I forced them to drive to the lake and walk home. They ate ice cream and walked with a general good attitude. Then attended afternoon camp and went swimming with me where Robbie had to be redirected/ corrected repeatedly but was generally sweet. Went to afternoon camp, then a babysitter where he got along with Penny and drew pictures, but apparently only ate churros for dinner. Had to leave disco bingo because it was too loud, which was frustrating because it was a fun camp activity. Ate a hot dog at 9pm and went to bed.', NULL, '🏊', 'positive', '[]'::jsonb, 5, 1784691270327, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('4688bb36-7413-42b2-959d-dd1ede9cbf61', 'profile-1780169301356', 'medication', 1780723577638, NULL, '[]'::jsonb, '2mg guanfacine', '[]'::jsonb, 'quick-tap', NULL, 'Medication Given', NULL, NULL, '[]'::jsonb, 6, 1780723577639, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('f471d285-8ce5-4dd8-a9c7-97eeffec6c0d', 'profile-1780169301356', 'aggression', 1780807599983, NULL, '[]'::jsonb, 'Threw lego creation across the room', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '😠', 'negative', '[]'::jsonb, 6, 1780807600079, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('4e596814-abdb-42e2-b68c-be4f01e732fa', 'profile-1780169301356', 'medication', 1781155856600, NULL, '[]'::jsonb, 'Took his medicine', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '💊', 'neutral', '[]'::jsonb, 6, 1781155856698, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('58a2d0d7-3c46-4b41-82b7-3b146ca87971', 'profile-1780169301356', 'poor_sleep', 1781240356304, NULL, '[]'::jsonb, 'Difficult at bedtime', '[]'::jsonb, 'voice', 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', NULL, '😏', 'negative', '[]'::jsonb, 6, 1781240356411, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('e78686fe-d2b2-4ae7-9e11-cd1b775e4d8e', 'profile-1780169301356', 'poor_transitions', 1781290800000, NULL, '[]'::jsonb, 'Dysregulated when transitioning from comics to bath', '[]'::jsonb, 'quick-tap', NULL, 'Poor Transitions', NULL, NULL, '[]'::jsonb, 6, 1781420827369, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b123782b-fd7a-456f-9460-a3f4f183960b', 'profile-1780169301356', 'bounceback', 1781495794604, NULL, '[]'::jsonb, 'Bounced back after meltdown', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '🐦‍🔥', 'positive', '[]'::jsonb, 6, 1781495794703, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('94e0c0a1-d4ce-4eac-abfd-8afa81c57719', 'profile-1780169301356', 'good_sleep', 1781636400000, NULL, '[]'::jsonb, 'Went to bed without any fuss', '[]'::jsonb, 'voice', 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', NULL, '😴', 'positive', '[]'::jsonb, 6, 1781756594989, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3a27b29c-e65c-434b-8e0f-72d4d65b1964', 'profile-1780169301356', 'tired', 1781756264543, NULL, '[]'::jsonb, 'Went to bed earlier than normal', '[]'::jsonb, 'voice', 'Robbie went to his last day of first grade today. I am unsure how it went during the day, but at pickup he was despondent and unable to attend the end of year party because of his sadness that he was not going to be able to play with Albie. He wanted to go only if he could play with his friend. I told him, unfortunately, that he couldn''t. He began to cry and said, get me out of here. So I took him home. I offered multiple alternatives like different restaurants or activities, but he was in shutdown and very sad. His lips were quivering. And then we ran into his friend, Gus, who is a year older and was with his mom on the front steps. And I said in a panic, Gus, would you like to join us for a play date? And Robbie, I checked with Robbie and Robbie said, okay. And Gus said, okay. So Gus came to our house and Gus played more with me than with Robbie. Robbie tried to engage him, but Robbie was laughing inappropriately and had strange social skills. Robbie peed his pants three times with Gus here, which Gus thought was strange. Gus asked for help with Robbie because Robbie was being weird. Robbie''s feelings were hurt because Gus didn''t pitch a baseball correctly at him. He got angry and hid in his room a couple of times. He was upset because Daisy was physically aggressive with him. And finally, Gus just wanted to leave. And so it was an unsuccessful play date in general, but Robbie was giddy for some of it and laughing, but he just didn''t have very good social skills and it was kind of awkward. Then we ended up having another family over for dinner that had kids and Robbie played very well with the 10-year-old boy, whose name is Thompson. And they played with pranks and Robbie ate a good dinner and was patient about waiting his turn to get on the back of the electrical bike. And even allowed Daisy to sit on his lap for the ride, but he got very tired and wanted to come home and went to bed earlier than normal. And it''s the beginning of summer.', NULL, '🥱', 'negative', '[]'::jsonb, 6, 1781756264650, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('f6899a20-4a04-4f27-93bf-4f621f6f5789', 'profile-1780169301356', 'sugar', 1781809200000, NULL, '[]'::jsonb, 'Ate lots of cookies', '[]'::jsonb, 'voice', 'It was the first official day of summer, Robbie woke up in a good mood and played wonderfully with his nanny, Hyanna, and Andy. He did a choreographed dance with Hyanna that he wanted to show mom. He built an incredibly complex avocado land with Andy involving multiple surfaces and toys and then had Hyanna record a 10 minute video explaining all the creative secret passageways, helicopter pads, etc. of his creation. He also cleaned it up with her help without much prompting. Robbie went across the street to his neighbor''s house and played well with Jasper and Kai and Griffin in his basement with limited expected drama. He was in good spirits and ate well, lots of cookies but also other things, all day.', NULL, '🍬', 'positive', '[]'::jsonb, 6, 1781931282739, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9b2329aa-fa78-4c2e-bb25-f8bf84204622', 'profile-1780169301356', 'watched_tv', 1781930549768, NULL, '[]'::jsonb, 'Watched TV before bed', '[]'::jsonb, 'voice', 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', NULL, '📺', 'neutral', '[]'::jsonb, 6, 1781930549868, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b7c806f6-9618-4b38-b790-953a99f28a91', 'profile-1780169301356', 'medication', 1782500400000, NULL, '[]'::jsonb, 'Took his medicine', '[]'::jsonb, 'voice', 'Mixed day. Woke up at 2am when Andy was begging for water, and Robbie was unkind to him, then Grouch hit breakfast. He made a lot of noise despite multiple warnings about mops sleeping, but eventually stopped. He refused to put on shoes and was non-compliant, but did get into the car. He was crying softly and holding his stuffed animal avocado. He couldn''t tell me what was wrong, but allowed for a hug. After camp, for reward points, he explained that he was upset earlier because his friend Anthony wouldn''t be at camp. He drew some ideas for the car competition at dinner. He took his medicine and went to bed okay.', NULL, '💊', 'neutral', '[]'::jsonb, 6, 1782792443048, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('297016ec-3541-4ce7-bccb-0188090f2e62', 'profile-1780169301356', 'kindness', 1782759600000, NULL, '[]'::jsonb, 'Sweet with Daisy', '[]'::jsonb, 'quick-tap', NULL, 'Kindness', NULL, 'positive', '[]'::jsonb, 6, 1782867744742, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b06c5bf0-c44b-475a-a150-210a32497c21', 'profile-1780169301356', 'sibling_harmony', 1782846000000, NULL, '[]'::jsonb, 'Entertained siblings with stories on drive home', '[]'::jsonb, 'voice', 'Great day. Woke up helpful and had a good breakfast. Good and quiet. In the car to camp. At camp played with two friends and did a big hike. Did not eat much. On drive home from camp entertained siblings the whole way with stories about his day and funny voices. Was a good sport about family outing to Highlands Mountain. Played nicely with and was brave around other kids. Was brave around dogs as well. Was patient with Daisy when she tried to hit him. Playful and silly. Though didn''t listen to mom a few times when she asked for help. Came home and asked for silence because his dry lips hurt. Drew a comic book with mom. Attempted to sleep with Daisy but gave up when she screamed too much. Was persuaded back out of kindness to his sister. Awesome day overall. Banked many points and was okay about not being able to spend them tonight.', NULL, '🫂', 'positive', '[]'::jsonb, 6, 1783138713931, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('892f0295-ec39-4197-8fda-5a39b1979715', 'profile-1780169301356', 'medication', 1783796400000, NULL, '[]'::jsonb, 'Took his medicine before falling asleep', '[]'::jsonb, 'voice', 'Robbie had a good day on mom''s birthday. He woke up around the same time mom did and gave her a card. He was relatively kind to his siblings and he stayed at home throughout much of the afternoon while mom went out with a friend. Robbie was really patient in the evening when we went on a family outing to the summer festival on Mercer Island to see the fireworks and he stayed up until past ten. He fell asleep in the car on the way home. He took his medicine right before falling asleep.', NULL, '💊', 'neutral', '[]'::jsonb, 6, 1783892095322, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('7b75c916-70fd-404b-9541-419b35b2f249', 'profile-1780169301356', 'medication', 1784002068317, NULL, '[]'::jsonb, 'Took his medicine', '[]'::jsonb, 'voice', 'A mixed to good day for Robbie who went to camp. He came back and did swim lessons as well. He was a bit squirrely throughout the day and not really listening to his parents. He was kind to his sister and also kind to Andy, but he wasn''t respecting everyone''s personal space and it was difficult to get him into bed without horseplay. He did take his medicine and was helpful in cleaning dinner to some extent.', NULL, '💊', 'neutral', '[]'::jsonb, 6, 1784002068410, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('8ff0031d-045b-4a48-8cc4-3bfed1ab235e', 'profile-1780169301356', 'toilet_issue', 1784264573622, NULL, '[]'::jsonb, 'Spilled pee on carpet', '[]'::jsonb, 'voice', 'Robbie once again went to bike camp and swimming lessons today. In the late afternoon, he went across the street to the neighbor''s house to celebrate the birthday of his friends Jasper and Kai. He then stayed out of the house to play with friends in the neighborhood. He later came back and played soccer in the backyard with Kai and briefly attempted to sell more comics outside. He was pleasant in the evening and took his medicine. He did have a bathroom event at the very end of the day, however, where he spilled pee on his carpet.', NULL, '🚽', 'negative', '[]'::jsonb, 6, 1784264573725, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('0af4b2a6-946b-493e-b6e2-378eb1f5883e', 'profile-1780169301356', 'sneaky', 1784487600000, NULL, '[]'::jsonb, 'Sneaked candy and hid wrappers', '[]'::jsonb, 'voice', 'Mixed day. Robbie did not want to attend camp and instead joined Andy’s baby camp so they could stay together. He complained the entire day (about the pool temperature, the activities, etc) but was helpful when we couldn’t find Andy. We had a chat about why he hates camp so much and about being more positive. He skipped dinner in order to have quiet time in the tent. At some point he sneaked back into the tent to eat candy and hid the wrappers under his bed. ', NULL, '🥷', 'negative', '[]'::jsonb, 6, 1784691086787, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('a1fbe521-87a4-4710-b7b3-808dbef85e1e', 'profile-1780169301356', 'refusal', 1784574000000, NULL, '[]'::jsonb, 'Had to leave disco bingo because it was too loud', '[]'::jsonb, 'voice', 'Good morning, mixed rest of day. he drew instead of going to camp, cleaned up the wrappers. There was an incident with Andy in the bathrooms but it seems to have been Andy’s fault. After lunch Robbie cried that he couldn’t have a cookie and then refused to do anything but draw in the tent. I forced them to drive to the lake and walk home. They ate ice cream and walked with a general good attitude. Then attended afternoon camp and went swimming with me where Robbie had to be redirected/ corrected repeatedly but was generally sweet. Went to afternoon camp, then a babysitter where he got along with Penny and drew pictures, but apparently only ate churros for dinner. Had to leave disco bingo because it was too loud, which was frustrating because it was a fun camp activity. Ate a hot dog at 9pm and went to bed.', NULL, '🙅', 'negative', '[]'::jsonb, 6, 1784691270328, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b1ad9950-2760-45c5-80df-b11a83aa057b', 'profile-1780169301356', 'bounceback', 1780724062737, NULL, '[]'::jsonb, 'Much better in the evening, ate dinner, and was well behaved', '[]'::jsonb, 'quick-tap', NULL, 'Bounceback', NULL, NULL, '[]'::jsonb, 7, 1780724062739, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6e7b1dc5-a119-4c8f-bc2b-4bc5855b176e', 'profile-1780169301356', 'bounceback', 1780807599983, NULL, '[]'::jsonb, 'Had a quiet evening after meltdowns', '[]'::jsonb, 'voice', 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', NULL, '🐦‍🔥', 'positive', '[]'::jsonb, 7, 1780807600080, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('10da67bd-f4a8-432e-a515-0d8a3e2a29db', 'profile-1780169301356', 'good_sleep', 1781155856600, NULL, '[]'::jsonb, 'Went down for bed fairly easily', '[]'::jsonb, 'voice', 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', NULL, '😴', 'positive', '[]'::jsonb, 7, 1781155856700, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('9c457cbb-7792-479b-87b1-f4432435415d', 'profile-1780169301356', 'medication', 1781240356304, NULL, '[]'::jsonb, '2mg guanfacine', '[]'::jsonb, 'voice', 'Another day with mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', NULL, '💊', 'neutral', '[]'::jsonb, 7, 1781240356412, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('643e3f79-7f9f-4017-800b-0d0869634eeb', 'profile-1780169301356', 'bounceback', 1781290800000, NULL, '[]'::jsonb, 'Recovered quickly from dysregulation', '[]'::jsonb, 'voice', 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', NULL, '🐦‍🔥', 'positive', '[]'::jsonb, 7, 1781420804058, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('ccd12518-22d0-4d2c-bddc-48efc2b1a3b8', 'profile-1780169301356', 'family_adventure', 1781495794604, NULL, '[]'::jsonb, 'Picked up mom from the airport', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '🏕️', 'positive', '[]'::jsonb, 7, 1781495794704, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('e77734bc-3766-4849-adba-2fd279fc69c7', 'profile-1780169301356', 'medication', 1781636400000, NULL, '[]'::jsonb, 'Took medicine before bed', '[]'::jsonb, 'voice', 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', NULL, '💊', 'neutral', '[]'::jsonb, 7, 1781756594991, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3c165be3-9a2c-4542-85e6-bce642b2941f', 'profile-1780169301356', 'medication', 1781756277047, NULL, '[]'::jsonb, '2mg guanfacine', '[]'::jsonb, 'quick-tap', NULL, 'Medication Given', NULL, NULL, '[]'::jsonb, 7, 1781756277048, 0) ON CONFLICT (id) DO NOTHING;
