INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('108ff7de-6f8b-44fd-83f6-7084cd5b2a47', 'profile-1780169301356', 'fast_food', 1784574000000, NULL, '[]'::jsonb, 'Ate a hot dog at 9pm', '[]'::jsonb, 'voice', 'Good morning, mixed rest of day. he drew instead of going to camp, cleaned up the wrappers. There was an incident with Andy in the bathrooms but it seems to have been Andy’s fault. After lunch Robbie cried that he couldn’t have a cookie and then refused to do anything but draw in the tent. I forced them to drive to the lake and walk home. They ate ice cream and walked with a general good attitude. Then attended afternoon camp and went swimming with me where Robbie had to be redirected/ corrected repeatedly but was generally sweet. Went to afternoon camp, then a babysitter where he got along with Penny and drew pictures, but apparently only ate churros for dinner. Had to leave disco bingo because it was too loud, which was frustrating because it was a fun camp activity. Ate a hot dog at 9pm and went to bed.', NULL, '🍟', 'neutral', '[]'::jsonb, 7, 1784691270329, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('444e7b78-fa60-459b-8366-7e44a394aa97', 'profile-1780169301356', 'good_dinner', 1780724096940, NULL, '[]'::jsonb, 'Carrots and pasta + popsicle for dessert', '[]'::jsonb, 'quick-tap', NULL, 'Good Dinner', NULL, NULL, '[]'::jsonb, 8, 1780724096941, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('195ab215-2689-4d94-b76e-02b3c652d9af', 'profile-1780169301356', 'meltdown', 1780807606516, NULL, '[]'::jsonb, 'Wasn’t another a second serving of bread and butter', '[]'::jsonb, 'quick-tap', NULL, 'Meltdown', NULL, NULL, '[]'::jsonb, 8, 1780807606517, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('b1a3fb00-e580-4ec6-b675-3aeae8ed6340', 'profile-1780169301356', 'watched_tv', 1781290800000, NULL, '[]'::jsonb, 'Watched TV in the evening', '[]'::jsonb, 'voice', 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', NULL, '📺', 'neutral', '[]'::jsonb, 8, 1781420804059, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('8a80657f-f3e0-456a-8675-73b19cf555e7', 'profile-1780169301356', 'good_dinner', 1781495817436, NULL, '[]'::jsonb, 'Chicken, pineapple, nectarines', '[]'::jsonb, 'quick-tap', NULL, 'Good Dinner', NULL, NULL, '[]'::jsonb, 8, 1781495817437, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('72febe3e-3d15-4088-b786-36f1e98af0bf', 'profile-1780169301356', 'medication', 1781809200000, NULL, '[]'::jsonb, '2mg guanfacine', '[]'::jsonb, 'quick-tap', NULL, 'Medication Given', NULL, NULL, '[]'::jsonb, 8, 1781931291066, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6f201561-fa23-4993-bd72-b467b68e0e88', 'profile-1780169301356', 'brave', 1782846000000, NULL, '[]'::jsonb, 'Was brave around other kids', '[]'::jsonb, 'voice', 'Great day. Woke up helpful and had a good breakfast. Good and quiet. In the car to camp. At camp played with two friends and did a big hike. Did not eat much. On drive home from camp entertained siblings the whole way with stories about his day and funny voices. Was a good sport about family outing to Highlands Mountain. Played nicely with and was brave around other kids. Was brave around dogs as well. Was patient with Daisy when she tried to hit him. Playful and silly. Though didn''t listen to mom a few times when she asked for help. Came home and asked for silence because his dry lips hurt. Drew a comic book with mom. Attempted to sleep with Daisy but gave up when she screamed too much. Was persuaded back out of kindness to his sister. Awesome day overall. Banked many points and was okay about not being able to spend them tonight.', NULL, '🦁', 'positive', '[]'::jsonb, 8, 1783138713933, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('0cd46410-e82c-4c3c-9bb0-28bed395303d', 'profile-1780169301356', 'good_sleep', 1784574000000, NULL, '[]'::jsonb, 'Went to bed', '[]'::jsonb, 'voice', 'Good morning, mixed rest of day. he drew instead of going to camp, cleaned up the wrappers. There was an incident with Andy in the bathrooms but it seems to have been Andy’s fault. After lunch Robbie cried that he couldn’t have a cookie and then refused to do anything but draw in the tent. I forced them to drive to the lake and walk home. They ate ice cream and walked with a general good attitude. Then attended afternoon camp and went swimming with me where Robbie had to be redirected/ corrected repeatedly but was generally sweet. Went to afternoon camp, then a babysitter where he got along with Penny and drew pictures, but apparently only ate churros for dinner. Had to leave disco bingo because it was too loud, which was frustrating because it was a fun camp activity. Ate a hot dog at 9pm and went to bed.', NULL, '😴', 'positive', '[]'::jsonb, 8, 1784691270329, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('c5522369-3159-4fef-9772-eb314f021c92', 'profile-1780169301356', 'medication', 1780807658046, NULL, '[]'::jsonb, '2mg guanfacine', '[]'::jsonb, 'quick-tap', NULL, 'Medication Given', NULL, NULL, '[]'::jsonb, 9, 1780807658047, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('0de6e18f-af66-4e6c-8bcc-c9b532e83f00', 'profile-1780169301356', 'medication', 1781290800000, NULL, '[]'::jsonb, 'Took two milligrams of guanfacine', '[]'::jsonb, 'voice', 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', NULL, '💊', 'neutral', '[]'::jsonb, 9, 1781420804059, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6f513958-5664-4e6f-ab88-7c08c692e307', 'profile-1780169301356', 'drew_comics', 1781495794604, NULL, '[]'::jsonb, 'Drew comics and explained them', '[]'::jsonb, 'voice', 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', NULL, '🦸', 'neutral', '[]'::jsonb, 9, 1781495794705, 0) ON CONFLICT (id) DO NOTHING;
