INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('0f86de0d-2306-4418-b6e7-43c251074a6b', 'profile-1780169301356', 'stayed_home', 1780858800000, NULL, '[]'::jsonb, 'Played quietly at home', '[]'::jsonb, 'voice', 'Robbie had a good day. He started off the morning playing quietly and was well behaved while he stayed at home with the babysitter, Bella. Around midday, he had quality time with dad, playing baseball in the backyard. He also had good mom bonding time later in the afternoon. In the evening, the whole family went to the outdoor mall in University Village. We ate pizza for dinner, and Robbie played tag outside afterward with Andy, Daisy, and a new friend. He was very helpful cleaning up the playroom when we got home, and as a reward, he was allowed to watch Bluey on TV. He went down for bed easily after taking his medicine.', NULL, 'neutral', 'neutral', '[]'::jsonb, NULL, 1780970809887, 0) ON CONFLICT (id) DO NOTHING;
