INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('3262ca14-8f8d-4dd9-a43a-b6775c43a61e', 'profile-1780169301356', 'good_dinner', 1780945200000, NULL, '[]'::jsonb, 'Ate more dinner later at night', '[]'::jsonb, 'voice', 'Good day. Robbie was on his best behavior as he wanted to be rewarded with toy pranks. He and dad had more good child-directed interaction time playing baseball in the backyard. He was sweet with his sister in the evening, carrying her around as she giggled. He had a half-hearted dinner, which he had more of later in the night before bed since he got hungry. He watched the Knicks basketball game as the family went to bed without any issue, took his medicine.', NULL, '😋', 'positive', '[]'::jsonb, NULL, 1781067366223, 0) ON CONFLICT (id) DO NOTHING;
