INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('1460c887-afbe-4de4-9d3b-994c17b02092', 'profile-1780169301356', 'stayed_home', 1781420255446, NULL, '[]'::jsonb, 'Stayed home with babysitter', '[]'::jsonb, 'voice', 'Mom, out of town in South Carolina, woke up at 7 and was fairly well-behaved during the morning when he stayed home with our babysitter, Hyanna. Did baseball bonding time with Dad in the backyard in the late morning. He was a bit unkind with Andy here and there, but nothing egregious. Did comics. After Daisy awoke from her nap, we went to Michael''s to get balloons and tchotchkes. Robbie had an excellent dinner and ate all of his chicken, apples, and carrots. The kids watched TV in the evening before bed and Robbie had two bowls of cereal as he was still hungry after a big dinner. Took two milligrams of guanfacin.', NULL, '🏠', 'neutral', '[]'::jsonb, NULL, 1781420255541, 0) ON CONFLICT (id) DO NOTHING;
