INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('2c899f20-4f79-4b51-8b72-5481bde2eb2d', 'profile-1780169301356', 'good_sleep', 1781982000000, NULL, '[]'::jsonb, 'Slept in until around 8am', '[]'::jsonb, 'voice', 'Robbie had a decent day. He slept in until around 8am and stayed home with the nanny throughout the morning. He seemed relatively well behaved. In the afternoon, he played in the new wading pool that we bought for the backyard. Later in the day, he played with his siblings and they all watched Bluey together. Robbie also collaborated on a Father''s Day gift with his brother and sister. He got to bed easily and took his medicine. A fairly uneventful and pleasant day.', NULL, '😴', 'positive', '[]'::jsonb, NULL, 1782103181380, 0) ON CONFLICT (id) DO NOTHING;
