INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('67519f63-c8a5-4ade-b66b-ef0352297e22', 'profile-1780169301356', 'travel', 1782154800000, NULL, '[]'::jsonb, 'Traveled to Colorado with family', '[]'::jsonb, 'voice', 'Robbie was fantastic today, traveling with his mom and siblings to Colorado. He was helpful with his siblings across two airplanes. He sat next to strangers on the flights, even though he was scared to. He ate a good dinner, was polite to his grandmother. He was a wonderful boy today. He made comics and drew and read, watched iPad, and played games on the airplane. He did miss his dose of medicine.', NULL, '✈️', 'neutral', '[]'::jsonb, NULL, 1782276401152, 0) ON CONFLICT (id) DO NOTHING;
