INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('df1818ae-9185-4a28-8018-ccf7b30d4cee', 'profile-1780169301356', 'great_day', 1782277803997, NULL, '[]'::jsonb, 'Had a fantastic day', '[]'::jsonb, 'voice', 'Robbie had a fantastic day again. He woke up in a good mood and had a good breakfast and was helpful and plucky about getting out of the house on time for camp. He attended camp with a good attitude and had smiles for his counselors who remembered him. At pickup he had ice cream and played nicely with his siblings. He did cheat a bit at chess but was funny about it. When we got home he drew comics and was very interested in the reward system that his parents devised for him. He told me in detail about his day to earn rewards and said he''d made a new friend Anthony. He had a good dinner then got to earn 30 minutes of screen time, which was a game that he played together with mom. Then he went to bed with no resistance, maybe his best day ever.', NULL, '🌟', 'positive', '[]'::jsonb, NULL, 1782277804107, 0) ON CONFLICT (id) DO NOTHING;
