INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('e4cfc21a-3ac0-4684-8b8d-69a4d39e2336', 'profile-1780169301356', 'great_day', 1782327600000, NULL, '[]'::jsonb, 'Had another great day', '[]'::jsonb, 'voice', 'Robbie had another great day. He had a good breakfast and went off to camp without issue, even helping with his siblings in the car when they were agitated. At camp he went fishing, and when other kids were naughty with cursing language, Robbie did not participate. He transitioned nicely when it was time to go home and was very motivated by the reward system on the drive, being funny and doing voices. He went to dinner and he was the best behaved, drawing quietly at the table. He shared his ice cream with his sister when she was sad. When mom got injured in the hot tub, Robbie did not immediately help, but he was likely more scared than anything. He was disappointed that mom couldn''t play with him after, but he went to bed without a fuss. Mom forgot to give him medicine.', NULL, '🌟', 'positive', '[]'::jsonb, NULL, 1782503490830, 0) ON CONFLICT (id) DO NOTHING;
