INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('59ce7315-b9d0-4bcb-9caf-87cd309f0cef', 'profile-1780169301356', 'great_day', 1782586800000, NULL, '[]'::jsonb, 'Had an excellent breakfast with siblings', '[]'::jsonb, 'voice', 'Robbie was excellent and responsible and kind at breakfast with siblings, helpful and gentle. Went to a restaurant and was playful and a good listener. When his sister Daisy had a meltdown, he sat with her and was patient and loving. Attended a farmer''s market on purpose to face his fear of dogs to get extra points for bravery. Spent most of the rest of the day at home creating drawings for a building competition and making his own cities. Babysitter said he was best behaved of all the kids.', NULL, '🌟', 'positive', '[]'::jsonb, NULL, 1782706096907, 0) ON CONFLICT (id) DO NOTHING;
