INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('1f67a49e-6240-44d9-a260-64a38b81490a', 'profile-1780169301356', 'family_adventure', 1782706414781, NULL, '[]'::jsonb, 'Ate breakfast at a restaurant', '[]'::jsonb, 'voice', 'Robbie woke up in a good mood and went to breakfast at a restaurant. He ate a good meal and played nicely at the park. He went to trade in reward points at the pharmacy for pranks. He went to a bookstore and got angry when I wouldn''t buy him a comic. He said, what''s the point of coming here if I can''t get something? He became truculent and teary. We went to a creek where he played nicely until it was time to leave, and he pushed his sister and was very afraid of dogs, despite mom being too ill to carry him. He played at home quietly, though he did roughhouse with his brother Andy. Went out reluctantly for another outing to the playground w he thought briefly that we left him and was sad. He was creative at dinner, making a person out of pretzel dough, but didn''t eat much. He had yogurt for dessert, bathed nicely, watched a cartoon with siblings, played a game in the cul-de-sac without being very courteous to younger siblings. He traded in his reward points for prank games and earned extra points by recapping his day and explaining his emotions from earlier.', NULL, '🎡', 'positive', '[]'::jsonb, NULL, 1782706414914, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('eb217435-fe39-4f53-ac01-a81d418aed98', 'profile-1780169301356', 'naughty', 1782706414781, NULL, '[]'::jsonb, 'Got angry at bookstore for not buying comic', '[]'::jsonb, 'voice', 'Robbie woke up in a good mood and went to breakfast at a restaurant. He ate a good meal and played nicely at the park. He went to trade in reward points at the pharmacy for pranks. He went to a bookstore and got angry when I wouldn''t buy him a comic. He said, what''s the point of coming here if I can''t get something? He became truculent and teary. We went to a creek where he played nicely until it was time to leave, and he pushed his sister and was very afraid of dogs, despite mom being too ill to carry him. He played at home quietly, though he did roughhouse with his brother Andy. Went out reluctantly for another outing to the playground w he thought briefly that we left him and was sad. He was creative at dinner, making a person out of pretzel dough, but didn''t eat much. He had yogurt for dessert, bathed nicely, watched a cartoon with siblings, played a game in the cul-de-sac without being very courteous to younger siblings. He traded in his reward points for prank games and earned extra points by recapping his day and explaining his emotions from earlier.', NULL, '😈', 'negative', '[]'::jsonb, NULL, 1782706414916, 0) ON CONFLICT (id) DO NOTHING;
