INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('c514388f-d7c4-482a-8e8b-25870034f1f9', 'profile-1780169301356', 'great_day', 1782932400000, NULL, '[]'::jsonb, 'Had last day of camp', '[]'::jsonb, 'voice', 'Wednesday was a good day. Robbie had his last day of camp. He was excited to see his friend and looking forward to seeing Anthony in August. We went out to dinner for our last evening. He was motivated by points. He didn''t eat very much, but he made a pretzel. He was a little grouchy about the drink situation, but he was overall pleasant. It was a positive day. He took his medicine.', NULL, '🌟', 'positive', '[]'::jsonb, NULL, 1783139761764, 0) ON CONFLICT (id) DO NOTHING;
