INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('fefee99d-6bda-4ef0-bbf1-1bee59872172', 'profile-1780169301356', 'creative', 1783138485595, NULL, '[]'::jsonb, 'Made a fort out of pillows', '[]'::jsonb, 'voice', 'A fairly mixed day. Robbie made a fort out of pillows in the morning but didn''t clean it, and the babysitter did ultimately. He exercised outside with Dad and Andy and watched the soccer game with Dad afterwards. In the afternoon, the whole family went to Magnolia Park. Robbie played well there and was sweet to his sister, pushing her on the swing. The family went on an adventure afterwards to eat at Serendipity, and Robbie had a good dinner there. He interrupted a lot in the evening and didn''t observe physical boundaries very well. He took his medicine.', NULL, '🧠', 'neutral', '[]'::jsonb, NULL, 1783138485707, 0) ON CONFLICT (id) DO NOTHING;
