INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('dfcb437f-63d9-41c7-9672-9e1af1322da5', 'profile-1780169301356', 'good_day', 1783230923930, NULL, '[]'::jsonb, 'Had a good day despite siblings'' behavior', '[]'::jsonb, 'voice', 'A good day for Robbie on a day when his siblings, Andy and Daisy, were particularly difficult. Robbie was fairly quiet throughout the morning. He created a little reading nook for himself and covered himself in a blanket while he read The Investigators. He got upset multiple times when his brother and sister weren''t giving him adequate space to build blocks, but he handled that situation well and was able to avoid a meltdown. He ate a good lunch of chicken nuggets, which he asked for earlier than his normal lunchtime. He was sweet to his sister when the family went to Ella Bailey Park together. He pushed his sister in the swing after she insisted on him doing so. Robbie had a decent dinner and we complimented him at the dinner table on his good behavior for the day. He took his medicine before bed.', NULL, '🌟', 'positive', '[]'::jsonb, NULL, 1783230924024, 0) ON CONFLICT (id) DO NOTHING;
