INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('478168d6-262c-49d9-9803-a95895761bb9', 'profile-1780169301356', 'meltdown', 1783537200000, NULL, '[]'::jsonb, 'Had a meltdown before camp', '[]'::jsonb, 'voice', 'This was a tough day for Robbie. He really did not want to go to camp in the morning and had a full meltdown and shutdown. Before eventually leaving for camp, mom had to write a note to the camp counselor explaining that Robbie did not need to ride his bike today and could sit on the side for a while. He came home later in a decent mood, but it was tough to overcome the stormy events of the morning. Mom and dad did have a helpful discussion with the child psychologist and he advised us to do a better job of validating Robbie''s feelings in the moment to get him to calm down from his meltdown mood. He was generally good throughout the rest of the day and did take his medicine before bed.', NULL, '🌊', 'negative', '[]'::jsonb, NULL, 1784002228426, 0) ON CONFLICT (id) DO NOTHING;
