INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('af989cab-cd2f-4c23-bb98-62b2044ffdb6', 'profile-1780169301356', 'good_sleep', 1783752285754, NULL, '[]'::jsonb, 'Went to bed without an issue', '[]'::jsonb, 'voice', 'Robbie had a good day. He went with his brother, Andy, in the morning to a trampoline park with the nanny, Rihanna. He didn''t have camp today and was generally in a good mood. He stayed home with the nanny while mom and dad ran errands in North Bend. Robbie was excited to bake a birthday cake for mom and so he and dad went to the grocery store to get ingredients and worked on the cake when they got home. Robbie ultimately got distracted by a program that mom put on the TV, which was fine. He went to bed without an issue with his medicine.', NULL, '😴', 'positive', '[]'::jsonb, NULL, 1783752285838, 0) ON CONFLICT (id) DO NOTHING;
