INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('ed2de5cb-f0dd-48f8-b73f-bed2c3421245', 'profile-1780169301356', 'great_day', 1783916446896, NULL, '[]'::jsonb, 'Had an excellent day', '[]'::jsonb, 'voice', 'Robbie had an excellent day. He was well behaved in the morning and then we went on a family adventure to eat lunch at Serendipity where he had sliders and was kind to his sister. He watched a lot of TV when we got home as we were having a lazy Sunday after a late night out to watch the fireworks. In the evening, Robbie went with Dad to the grocery store and was helpful picking out produce and other items. When we got home, he watched more TV before eating a dinner of chicken nuggets and french fries. He was well behaved in the evening and took his medicine before bed.', NULL, '🌟', 'positive', '[]'::jsonb, NULL, 1783916446990, 0) ON CONFLICT (id) DO NOTHING;
