INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('6a7c0ce8-ffd4-438c-a019-344e998362f6', 'profile-1780169301356', 'camp', 1784142000000, NULL, '[]'::jsonb, 'Attended bike camp with brother', '[]'::jsonb, 'voice', 'Robbie had a fine day. He went to bike camp with his brother and then to swimming lessons with mom. When he got home, he wanted to sell his comics outside our house with his toy cash register and small table. He sold two comics and was happy about the money he received. Several of his friends came over and then Robbie rode his bike to his friend''s house by himself. Robbie later refused to clean the chairs and tables from the front of the house and had to be helped. Robbie was able to trade in points for a root beer float and five dollars cash. He took his medicine.', NULL, '🏕️', 'positive', '[]'::jsonb, NULL, 1784264410809, 0) ON CONFLICT (id) DO NOTHING;
