INSERT INTO events (id, child_profile_id, event_type, timestamp, severity, tags, notes, persons, source, transcript, custom_label, custom_emoji, valence, context_entry_refs, sequence_order, created_at, synced) VALUES ('1ababadf-52f0-4e6d-acf8-31dadd1aaef8', 'profile-1780169301356', 'refusal', 1784314800000, NULL, '[]'::jsonb, 'Refused to put bike back', '[]'::jsonb, 'voice', 'Robbie had a good day, he refused to put his bike back at one point and then acquiesced to do it when we temporarily withheld dinner. We took a family adventure to the public pool and Robbie was both well-behaved and kind to Andy. He was brave in biking to and from the pool, no issues at night, and he took his medicine.', NULL, '🙅', 'negative', '[]'::jsonb, NULL, 1784415441761, 0) ON CONFLICT (id) DO NOTHING;
