INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('7c4f86fc-3e7a-410f-88b0-30c240d19a0f', 'profile-1780169301356', 1784574000000, 'Good morning, mixed rest of day. he drew instead of going to camp, cleaned up the wrappers. There was an incident with Andy in the bathrooms but it seems to have been Andy’s fault. After lunch Robbie cried that he couldn’t have a cookie and then refused to do anything but draw in the tent. I forced them to drive to the lake and walk home. They ate ice cream and walked with a general good attitude. Then attended afternoon camp and went swimming with me where Robbie had to be redirected/ corrected repeatedly but was generally sweet. Went to afternoon camp, then a babysitter where he got along with Penny and drew pictures, but apparently only ate churros for dinner. Had to leave disco bingo because it was too loud, which was frustrating because it was a fun camp activity. Ate a hot dog at 9pm and went to bed.', 1784574000000, 'voice', 1784691270230, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('5d6395f6-7aa6-460d-8e17-21409048e2b3', 'profile-1780169301356', 1784487600000, 'Mixed day. Robbie did not want to attend camp and instead joined Andy’s baby camp so they could stay together. He complained the entire day (about the pool temperature, the activities, etc) but was helpful when we couldn’t find Andy. We had a chat about why he hates camp so much and about being more positive. He skipped dinner in order to have quiet time in the tent. At some point he sneaked back into the tent to eat candy and hid the wrappers under his bed. ', 1784487600000, 'voice', 1784691086672, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('db8b0e8f-cdb4-48af-ae94-6120a52c5128', 'profile-1780169301356', 1784401200000, 'Today was a travel day. Robbie was overall pretty good with a couple of tantrums, not meltdowns. He ate mainly snacks and junk food because we were traveling and driving, and he was uninterested in making new friends once we joined the camp. He was pleasant in general and helped Andy with his iPad. He repeatedly said “this is boring” aloud during camp events, which was awkward. ', 1784401200000, 'voice', 1784691000819, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('142e14d1-b65b-420e-9490-0d65830da134', 'profile-1780169301356', 1784314800000, 'Robbie had a good day, he refused to put his bike back at one point and then acquiesced to do it when we temporarily withheld dinner. We took a family adventure to the public pool and Robbie was both well-behaved and kind to Andy. He was brave in biking to and from the pool, no issues at night, and he took his medicine.', 1784314800000, 'voice', 1784415441681, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('0d1c26d5-2477-4deb-89ce-c916651d3e3a', 'profile-1780169301356', 1784264573622, 'Robbie once again went to bike camp and swimming lessons today. In the late afternoon, he went across the street to the neighbor''s house to celebrate the birthday of his friends Jasper and Kai. He then stayed out of the house to play with friends in the neighborhood. He later came back and played soccer in the backyard with Kai and briefly attempted to sell more comics outside. He was pleasant in the evening and took his medicine. He did have a bathroom event at the very end of the day, however, where he spilled pee on his carpet.', 1784264573622, 'voice', 1784264573622, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('13057899-e599-48eb-9551-25cd674276f5', 'profile-1780169301356', 1784142000000, 'Robbie had a fine day. He went to bike camp with his brother and then to swimming lessons with mom. When he got home, he wanted to sell his comics outside our house with his toy cash register and small table. He sold two comics and was happy about the money he received. Several of his friends came over and then Robbie rode his bike to his friend''s house by himself. Robbie later refused to clean the chairs and tables from the front of the house and had to be helped. Robbie was able to trade in points for a root beer float and five dollars cash. He took his medicine.', 1784142000000, 'voice', 1784264410716, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('18b61f64-2b58-4c89-8816-5ac571b7734e', 'profile-1780169301356', 1784055600000, 'Robbie had a decent day. He went to bike camp and swimming lessons. Later, the whole family went to the park and then got pizza at the pizzeria. Robbie was kind to his sister throughout the day and took his medicine before bed.', 1784055600000, 'voice', 1784264277505, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('89b73b32-a431-4dc9-83bb-d63718707956', 'profile-1780169301356', 1784002068317, 'A mixed to good day for Robbie who went to camp. He came back and did swim lessons as well. He was a bit squirrely throughout the day and not really listening to his parents. He was kind to his sister and also kind to Andy, but he wasn''t respecting everyone''s personal space and it was difficult to get him into bed without horseplay. He did take his medicine and was helpful in cleaning dinner to some extent.', 1784002068317, 'voice', 1784002068319, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('046e95eb-69fe-4fa8-b431-06d3a1b18aaf', 'profile-1780169301356', 1783916446896, 'Robbie had an excellent day. He was well behaved in the morning and then we went on a family adventure to eat lunch at Serendipity where he had sliders and was kind to his sister. He watched a lot of TV when we got home as we were having a lazy Sunday after a late night out to watch the fireworks. In the evening, Robbie went with Dad to the grocery store and was helpful picking out produce and other items. When we got home, he watched more TV before eating a dinner of chicken nuggets and french fries. He was well behaved in the evening and took his medicine before bed.', 1783916446896, 'voice', 1783916446897, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('2a19df82-7b48-4b86-9575-221d3defc803', 'profile-1780169301356', 1783796400000, 'Robbie had a good day on mom''s birthday. He woke up around the same time mom did and gave her a card. He was relatively kind to his siblings and he stayed at home throughout much of the afternoon while mom went out with a friend. Robbie was really patient in the evening when we went on a family outing to the summer festival on Mercer Island to see the fireworks and he stayed up until past ten. He fell asleep in the car on the way home. He took his medicine right before falling asleep.', 1783796400000, 'voice', 1783892095226, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('426dcc5c-1b4d-4564-b72b-1330fd7edb8d', 'profile-1780169301356', 1783752285754, 'Robbie had a good day. He went with his brother, Andy, in the morning to a trampoline park with the nanny, Rayanna. He didn''t have camp today and was generally in a good mood. He stayed home with the nanny while mom and dad ran errands in North Bend. Robbie was excited to bake a birthday cake for mom and so he and dad went to the grocery store to get ingredients and worked on the cake when they got home. Robbie ultimately got distracted by a program that mom put on the TV, which was fine. He went to bed without an issue with his medicine.', 1783752285754, 'voice', 1783752285756, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('dc84e97d-ef4d-484f-bca3-3b54b6af4e3b', 'profile-1780169301356', 1783657661934, 'Robbie had a decent day. He woke up easily and didn''t fuss or whine about having to go to bike camp. He had a decent day at bike camp, and then afterwards, Mom, Dad, Andy, and Robbie went to Swanson''s to eat lunch, and he had a good lunch there. Then he stayed at Swanson''s nursery to pick out flowers with Mom and played with Andy. We then got home later, and Robbie was relatively well-behaved. He ate a decent dinner as well and went to bed relatively early. He took his medicine.', 1783657661934, 'voice', 1783657661936, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('d8a6baf6-74be-4dca-801b-2e008f1d0967', 'profile-1780169301356', 1783537200000, 'This was a tough day for Robbie. He really did not want to go to camp in the morning and had a full meltdown and shutdown. Before eventually leaving for camp, mom had to write a note to the camp counselor explaining that Robbie did not need to ride his bike today and could sit on the side for a while. He came home later in a decent mood, but it was tough to overcome the stormy events of the morning. Mom and dad did have a helpful discussion with the child psychologist and he advised us to do a better job of validating Robbie''s feelings in the moment to get him to calm down from his meltdown mood. He was generally good throughout the rest of the day and did take his medicine before bed.', 1783537200000, 'voice', 1784002228341, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('98a2c9f8-93f1-48ce-a566-5355e3cc5bfb', 'profile-1780169301356', 1783450800000, 'Robbie had a great day, he went to bike camp and was well behaved afterwards while dad was convalescing from surgery. He spent most of the day with mom and the babysitter. He was kind to his sister and took his medicine at bedtime.', 1783450800000, 'voice', 1784002281549, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('51142d23-69ed-4377-922a-f7bd5f00c32e', 'profile-1780169301356', 1783364400000, 'Robbie had a good day. He was on good behavior, went on an adventure with mom and Andy to Krispy Kreme and played baseball outside with dad. He was well behaved at night and took his medicine.', 1783364400000, 'voice', 1783458254657, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('4a42d715-4ecd-4b87-87bd-49ebd16e0fac', 'profile-1780169301356', 1783278000000, 'Robbie had a good day, he was on good behavior, went on an adventure with mom and Andy to Krispy Kreme and played baseball outside with dad. He hit a big home run and was proud of it. He was well behaved at night and took his medicine.', 1783278000000, 'voice', 1783458565310, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('5b3950c8-ad49-46bd-9c15-3b9014e8105c', 'profile-1780169301356', 1783230923930, 'A good day for Robbie on a day when his siblings, Andy and Daisy, were particularly difficult. Robbie was fairly quiet throughout the morning. He created a little reading nook for himself and covered himself in a blanket while he read The Investigators. He got upset multiple times when his brother and sister weren''t giving him adequate space to build blocks, but he handled that situation well and was able to avoid a meltdown. He ate a good lunch of chicken nuggets, which he asked for earlier than his normal lunchtime. He was sweet to his sister when the family went to Ella Bailey Park together. He pushed his sister in the swing after she insisted on him doing so. Robbie had a decent dinner and we complimented him at the dinner table on his good behavior for the day. He took his medicine before bed.', 1783230923930, 'voice', 1783230923932, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('7598224a-4f65-4891-b9c2-f3ec303bbd08', 'profile-1780169301356', 1783138485595, 'A fairly mixed day. Robbie made a fort out of pillows in the morning but didn''t clean it, and the babysitter did ultimately. He exercised outside with Dad and Andy and watched the soccer game with Dad afterwards. In the afternoon, the whole family went to Magnolia Park. Robbie played well there and was sweet to his sister, pushing her on the swing. The family went on an adventure afterwards to eat at Serendipity, and Robbie had a good dinner there. He interrupted a lot in the evening and didn''t observe physical boundaries very well. He took his medicine.', 1783138485595, 'voice', 1783138485597, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('92c524bd-1b1b-461d-89bb-eabeabd98f9b', 'profile-1780169301356', 1783018800000, 'Robbie had a really good day. He woke up early, went to the airport, flew on airplanes, sat by himself, ate normal food, was able to hold his pee, watched a ton of iPad time, but that was okay because it was a travel day. He was pleasant and helpful and had a very good day. Took his medicine, flew from Aspen, Colorado to Seattle.', 1783018800000, 'voice', 1783139663118, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('3ce42268-4050-48f7-ad22-10e91d4826ca', 'profile-1780169301356', 1782932400000, 'Wednesday was a good day. Robbie had his last day of camp. He was excited to see his friend and looking forward to seeing Anthony in August. We went out to dinner for our last evening. He was motivated by points. He didn''t eat very much, but he made a pretzel. He was a little grouchy about the drink situation, but he was overall pleasant. It was a positive day. He took his medicine.', 1782932400000, 'voice', 1783139761672, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('bdfc2cf5-2a7a-4823-a2b4-0adaa77c7a02', 'profile-1780169301356', 1782846000000, 'Great day. Woke up helpful and had a good breakfast. Good and quiet. In the car to camp. At camp played with two friends and did a big hike. Did not eat much. On drive home from camp entertained siblings the whole way with stories about his day and funny voices. Was a good sport about family outing to Highlands Mountain. Played nicely with and was brave around other kids. Was brave around dogs as well. Was patient with Daisy when she tried to hit him. Playful and silly. Though didn''t listen to mom a few times when she asked for help. Came home and asked for silence because his dry lips hurt. Drew a comic book with mom. Attempted to sleep with Daisy but gave up when she screamed too much. Was persuaded back out of kindness to his sister. Awesome day overall. Banked many points and was okay about not being able to spend them tonight.', 1782846000000, 'voice', 1783138713807, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('1707aab5-84c7-4f22-a179-a7ce7a8ab499', 'profile-1780169301356', 1782759600000, 'Mixed day. Robbie was okay about getting off to camp, a little bit slow in the morning. Camp went okay as far as I know. Then afterward was really hungry and we went to a Thai place where he had a meltdown over not being allowed a soda. He did get a strawberry milk boba, but didn''t like it. He refused to eat and was crying and screaming in the grocery store for gum and candy. Eventually calmed down at home when we read together on the hammock and he traded in reward points for a prank. Had a good bath and was sweet about sleeping in his sister''s room to keep her feeling safe.', 1782759600000, 'voice', 1782867736736, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('a0fa6e8d-aa2b-487d-a7ca-ba8c4934faf6', 'profile-1780169301356', 1782706414781, 'Robbie woke up in a good mood and went to breakfast at a restaurant. He ate a good meal and played nicely at the park. He went to trade in reward points at the pharmacy for pranks. He went to a bookstore and got angry when I wouldn''t buy him a comic. He said, what''s the point of coming here if I can''t get something? He became truculent and teary. We went to a creek where he played nicely until it was time to leave, and he pushed his sister and was very afraid of dogs, despite mom being too ill to carry him. He played at home quietly, though he did roughhouse with his brother Andy. Went out reluctantly for another outing to the playground w he thought briefly that we left him and was sad. He was creative at dinner, making a person out of pretzel dough, but didn''t eat much. He had yogurt for dessert, bathed nicely, watched a cartoon with siblings, played a game in the cul-de-sac without being very courteous to younger siblings. He traded in his reward points for prank games and earned extra points by recapping his day and explaining his emotions from earlier.', 1782706414781, 'voice', 1782706414781, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('3e66b1f9-3669-4d08-8adc-8ea05077d297', 'profile-1780169301356', 1782586800000, 'Robbie was excellent and responsible and kind at breakfast with siblings, helpful and gentle. Went to a restaurant and was playful and a good listener. When his sister Daisy had a meltdown, he sat with her and was patient and loving. Attended a farmer''s market on purpose to face his fear of dogs to get extra points for bravery. Spent most of the rest of the day at home creating drawings for a building competition and making his own cities. Babysitter said he was best behaved of all the kids.', 1782586800000, 'voice', 1782706096820, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('08f33177-9f26-4444-9448-f1f942097d42', 'profile-1780169301356', 1782500400000, 'Mixed day. Woke up at 2am when Andy was begging for water, and Robbie was unkind to him, then Grouch hit breakfast. He made a lot of noise despite multiple warnings about mops sleeping, but eventually stopped. He refused to put on shoes and was non-compliant, but did get into the car. He was crying softly and holding his stuffed animal avocado. He couldn''t tell me what was wrong, but allowed for a hug. After camp, for reward points, he explained that he was upset earlier because his friend Anthony wouldn''t be at camp. He drew some ideas for the car competition at dinner. He took his medicine and went to bed okay.', 1782500400000, 'voice', 1782792442950, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('1b9977e4-bf51-45a4-95a1-24ddcc50c760', 'profile-1780169301356', 1782414000000, 'Robbie had another great day, got off to school with no problem. After school he did a bingo game and played with his friend Anthony. He was a sweet brother and was good about explaining his day. He''s getting better about recapping stories in an interesting way. He was even kind to a small boy in the park. He traded in his points for pranks and did not throw a fit when one prank broke immediately. He went to sleep without issue and took his medicine.', 1782414000000, 'voice', 1782503736785, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('071a932c-3f3f-4645-8431-47894aaa5c71', 'profile-1780169301356', 1782327600000, 'Robbie had another great day. He had a good breakfast and went off to camp without issue, even helping with his siblings in the car when they were agitated. At camp he went fishing, and when other kids were naughty with cursing language, Robbie did not participate. He transitioned nicely when it was time to go home and was very motivated by the reward system on the drive, being funny and doing voices. He went to dinner and he was the best behaved, drawing quietly at the table. He shared his ice cream with his sister when she was sad. When mom got injured in the hot tub, Robbie did not immediately help, but he was likely more scared than anything. He was disappointed that mom couldn''t play with him after, but he went to bed without a fuss. Mom forgot to give him medicine.', 1782327600000, 'voice', 1782503490729, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('f3f8fc57-210a-44d3-97f4-abe64225c036', 'profile-1780169301356', 1782277803997, 'Robbie had a fantastic day again. He woke up in a good mood and had a good breakfast and was helpful and plucky about getting out of the house on time for camp. He attended camp with a good attitude and had smiles for his counselors who remembered him. At pickup he had ice cream and played nicely with his siblings. He did cheat a bit at chess but was funny about it. When we got home he drew comics and was very interested in the reward system that his parents devised for him. He told me in detail about his day to earn rewards and said he''d made a new friend Anthony. He had a good dinner then got to earn 30 minutes of screen time, which was a game that he played together with mom. Then he went to bed with no resistance, maybe his best day ever.', 1782277803997, 'voice', 1782277803999, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('d3b81373-c466-470d-8715-5fc660b0605d', 'profile-1780169301356', 1782154800000, 'Robbie was fantastic today, traveling with his mom and siblings to Colorado. He was helpful with his siblings across two airplanes. He sat next to strangers on the flights, even though he was scared to. He ate a good dinner, was polite to his grandmother. He was a wonderful boy today. He made comics and drew and read, watched iPad, and played games on the airplane. He did miss his dose of medicine.', 1782154800000, 'voice', 1782276401053, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('96b7018e-c60b-4135-93ec-bffc0ed8dd33', 'profile-1780169301356', 1782103282339, 'Good day for Robbie. He woke up on Father''s Day after sleeping in and collaborated with his mom on Father''s Day gifts and baking of a special treat for dad. He stayed home with Rayanna in the morning and I didn''t hear of any incidents of bad behavior. In the afternoon he went outside in the wading pool in the backyard with his brother and sister and then the whole family went to see a movie in Toy Story 5 in the late afternoon. Afterwards the whole family went to a Thai restaurant and we got home with enough time for him to bathe before bed. He took his medicine and went down without a struggle.', 1782103282339, 'voice', 1782103282339, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('ac37bb82-a3a0-4faf-8637-e33bc0200168', 'profile-1780169301356', 1781982000000, 'Robbie had a decent day. He slept in until around 8am and stayed home with the nanny throughout the morning. He seemed relatively well behaved. In the afternoon, he played in the new wading pool that we bought for the backyard. Later in the day, he played with his siblings and they all watched Bluey together. Robbie also collaborated on a Father''s Day gift with his brother and sister. He got to bed easily and took his medicine. A fairly uneventful and pleasant day.', 1781982000000, 'voice', 1782103181295, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('61390545-eb5a-43a6-99c0-00ac84a2e401', 'profile-1780169301356', 1781930549768, 'Robbie had a really good day. He stayed at home with the nanny, Rayanna, in the morning and was generally well behaved. He did a lot of pretend play while he dressed up as a king and pretended that Andy was his butler. He used cushions from the couch to build a throne in Castle Keep and surprised us all by cleaning it up after he was done playing. We went on a family adventure to Discovery Park in the afternoon and after a couple of hours we all went to Wendy''s to get fast food. Robbie was pleasant in the car on the ride home and was rewarded with a movie before bed. He took his medicine before going to sleep.', 1781930549768, 'voice', 1781930549771, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('df2e2ac7-94a7-4b5a-b506-bbe4df94ba02', 'profile-1780169301356', 1781809200000, 'It was the first official day of summer, Robbie woke up in a good mood and played wonderfully with his nanny, Hyanna, and Andy. He did a choreographed dance with Hyanna that he wanted to show mom. He built an incredibly complex avocado land with Andy involving multiple surfaces and toys and then had Hyanna record a 10 minute video explaining all the creative secret passageways, helicopter pads, etc. of his creation. He also cleaned it up with her help without much prompting. Robbie went across the street to his neighbor''s house and played well with Jasper and Kai and Griffin in his basement with limited expected drama. He was in good spirits and ate well, lots of cookies but also other things, all day.', 1781809200000, 'voice', 1781931282642, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('952494cb-8b57-452b-918a-0a4c6de84626', 'profile-1780169301356', 1781756264543, 'Robbie went to his last day of first grade today. I am unsure how it went during the day, but at pickup he was despondent and unable to attend the end of year party because of his sadness that he was not going to be able to play with Albie. He wanted to go only if he could play with his friend. I told him, unfortunately, that he couldn''t. He began to cry and said, get me out of here. So I took him home. I offered multiple alternatives like different restaurants or activities, but he was in shutdown and very sad. His lips were quivering. And then we ran into his friend, Gus, who is a year older and was with his mom on the front steps. And I said in a panic, Gus, would you like to join us for a play date? And Robbie, I checked with Robbie and Robbie said, okay. And Gus said, okay. So Gus came to our house and Gus played more with me than with Robbie. Robbie tried to engage him, but Robbie was laughing inappropriately and had strange social skills. Robbie peed his pants three times with Gus here, which Gus thought was strange. Gus asked for help with Robbie because Robbie was being weird. Robbie''s feelings were hurt because Gus didn''t pitch a baseball correctly at him. He got angry and hid in his room a couple of times. He was upset because Daisy was physically aggressive with him. And finally, Gus just wanted to leave. And so it was an unsuccessful play date in general, but Robbie was giddy for some of it and laughing, but he just didn''t have very good social skills and it was kind of awkward. Then we ended up having another family over for dinner that had kids and Robbie played very well with the 10-year-old boy, whose name is Thompson. And they played with pranks and Robbie ate a good dinner and was patient about waiting his turn to get on the back of the electrical bike. And even allowed Daisy to sit on his lap for the ride, but he got very tired and wanted to come home and went to bed earlier than normal. And it''s the beginning of summer.', 1781756264543, 'voice', 1781756264545, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('c16f7141-95ee-4789-abb4-f020b77f82aa', 'profile-1780169301356', 1781636400000, 'Robbie had a fairly uneventful day. He drew comics after school, ate a good dinner and played nicely with his siblings. He went to bed without any fuss and took his medicine before bed. He was sad throughout the day about his broken friendship with Albie, but was encouragingly open about his emotions with mom and dad. He made an impressive lock structure with his Matchbox cars.', 1781636400000, 'voice', 1781756594894, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('8cfb4ea1-a125-49a7-a099-cbc1bfb122f9', 'profile-1780169301356', 1781586006069, 'Robbie had a fairly volatile day slash evening. He built a pillow fort in the living room after school, which is a toy structure he is notorious for not cleaning after. When asked to tidy it up before dinner, he had a meltdown and stormed off to his room. He came down shortly thereafter and had a good pleasant dinner. Mom tried to get him to clean again after dinner, but he was pretty lazy and uncooperative and did a half-hearted job. Mom had some good bonding time with him in his room later in the evening. He got to bed without issue and took 2mg of guanfacine before sleep.', 1781586006069, 'voice', 1781586006071, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('8a460798-4685-4b77-90f0-0645a1f9a89b', 'profile-1780169301356', 1781495794604, 'Robbie slept in in the morning and came downstairs around 8 a.m. He stayed home with the babysitter Ella and was fine until mid-morning. When dad returned home from the grocery store with Daisy, Andy and Robbie were watching TV. Robbie was asked to stop watching and clean before resuming his program and he became resistant and then angry before having a meltdown and shutting down in his room. He threw things and was generally incensed. He bounced back but it was a frustrating episode that was partly the fault of the babysitter for letting him watch TV to begin with. We picked up mom from the airport at 4 p.m. as a family and Robbie was pleasant through bedtime. He drew comics and was very proud of them when explaining them to mom. He took his two milligrams of guanfacin before sleep.', 1781495794604, 'voice', 1781495794606, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('7544b660-d0c7-4aba-87aa-d3e8497a5640', 'profile-1780169301356', 1781420255446, 'Mom, out of town in South Carolina, woke up at 7 and was fairly well-behaved during the morning when he stayed home with our babysitter, Hyanna. Did baseball bonding time with Dad in the backyard in the late morning. He was a bit unkind with Andy here and there, but nothing egregious. Did comics. After Daisy awoke from her nap, we went to Michael''s to get balloons and tchotchkes. Robbie had an excellent dinner and ate all of his chicken, apples, and carrots. The kids watched TV in the evening before bed and Robbie had two bowls of cereal as he was still hungry after a big dinner. Took two milligrams of guanfacin.', 1781420255446, 'voice', 1781420255448, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('afa3a4f3-9389-41e0-b086-89dace6b691c', 'profile-1780169301356', 1781290800000, 'Mom out of town in South Carolina, Robbie had no trouble getting ready for school and no incidents to report while there. Zion, our nanny, picked him up to take him to Andy''s graduation outdoors at Ella Bailey Park. Robbie had a lot of popsicles but played in an orderly and active fashion on the playground. He obediently left when we asked him to and was well-behaved on the way home. When we got home, he drew comics and was somewhat dysregulated when asked to bathe. He bounced back quickly from this, however. He and his siblings watched TV in the evening before bed. He took two milligrams of guanfacine.', 1781290800000, 'voice', 1781420803963, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('3cd7ebe1-002f-4349-9baa-dd29d2c764c8', 'profile-1780169301356', 1781240356304, 'Another day with Mom out of town. Robbie seemed relatively easy in the morning. I didn''t receive any negative reports about him while he was at school. He stayed a couple hours afterwards to play video games with his teacher, Mr. Nick, which is a prize he won at a silent auction a month ago. Robbie stayed at school even longer with our nanny, Zion, and his siblings to play on the school playground. Dad joined them there and played with them before driving them home to eat dinner. They all ate well and Robbie had dessert afterwards. He volunteered to take a bath and the kids earned a program afterwards and watched TV. Robbie was a little bit difficult at bedtime and got out of his bed several times but ultimately fell asleep. He took his medicine.', 1781240356304, 'voice', 1781240356306, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('22d49edd-d69b-454d-a41a-9edd262236e0', 'profile-1780169301356', 1781155856600, 'Robbie had a good day on the day that saw his mom leave town for a girl''s trip. He was well behaved in the morning and got dressed and left the house without much fuss. He was picked up from school by Karen for a play date and he hung out with her for a little while before asking to go home. He was very chill and docile throughout the evening. He ate a good dinner of steak and he had good manners and cleaned up after himself. He was mild mannered with his siblings. Robbie received a couple of reward toys consistent with a deal he had with his mom where good behavior would lead to these rewards. Robbie and his siblings were good enough to earn TV time in the evening and Robbie went down for bed fairly easily, although he did get up at one point to change his clothes. He took his medicine.', 1781155856600, 'voice', 1781155856602, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('6d659d7e-7412-4104-a09d-ebf62027e923', 'profile-1780169301356', 1781071166292, 'Robbie had a really good day. He was extremely well behaved in the evening. He read really quietly. He had a decent dinner. He had gone earlier in the day after school to an ice cream social with Mom and had really wanted to play with his friend, Allie, but the two of them have had to be separated recently because they''ve been naughty at times. So Robbie played baseball outside with Dad as a Dad bonding moment and he went to bed in the same room as his brother. He had his medicine before bed. All in all, a very controlled and regulated day.', 1781071166292, 'voice', 1781071166292, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('9d64a91d-6660-40f0-bf71-8d8c919fd2cc', 'profile-1780169301356', 1780945200000, 'Good day. Robbie was on his best behavior as he wanted to be rewarded with toy pranks. He and dad had more good child-directed interaction time playing baseball in the backyard. He was sweet with his sister in the evening, carrying her around as she giggled. He had a half-hearted dinner, which he had more of later in the night before bed since he got hungry. He watched the Knicks basketball game as the family went to bed without any issue, took his medicine.', 1780945200000, 'voice', 1781067366145, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('78bbdce4-77ec-4e90-9770-6869a9731af8', 'profile-1780169301356', 1780858800000, 'Robbie had a good day. He started off the morning playing quietly and was well behaved while he stayed at home with the babysitter, Bella. Around midday, he had quality time with dad, playing baseball in the backyard. He also had good mom bonding time later in the afternoon. In the evening, the whole family went to the outdoor mall in University Village. We ate pizza for dinner, and Robbie played tag outside afterward with Andy, Daisy, and a new friend. He was very helpful cleaning up the playroom when we got home, and as a reward, he was allowed to watch Bluey on TV. He went down for bed easily after taking his medicine.', 1780858800000, 'voice', 1780970809789, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('78af8b35-53e7-4d6e-a102-b952a91e631f', 'profile-1780169301356', 1780807599983, 'Today was yet another tough day, Robbie was okay in the morning when a babysitter came over until 2pm, however at about noon, Robbie was asked to clean up a space in the playroom that was messy and he denied making the mess even though I had seen him make it. When I insisted that he clean up, he got really upset, threw his fire truck, hit Andy on the way out of the room, and went upstairs as part of a meltdown. He wouldn''t talk to me when I went up to his room about a half hour later and he made a big mess in his room which I had to clean later in the day. Then we all went to Michaels to get art supplies for a family craft night and Robbie was excited throughout the shopping experience but got very upset at the end when we wouldn''t buy him a stuffed octopus and he cried. We went home and did some crafts and he was better but then around dinner time he was using potty language and we didn''t allow him to have a second helping of bread and butter so he threw a lego creation across the room and yet again went up to his room after a meltdown. He bounced back after that and had a quiet evening but it was overall a fairly trying day.', 1780807599983, 'voice', 1780807599983, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('70340fba-4f92-4f3a-973f-e2a0f52a4c36', 'profile-1780169301356', 1780723452298, 'Robbie had a rough day. He had a number of different school incidents during and after a field trip. He was misbehaving with his friend, Albie. They purposefully clogged a toilet at the school and then had to apologize to the custodian. When mom picked him up after school, Robbie threw a tantrum and intentionally peed himself, and daddy had to come to school with new clothes so they could leave together and Robbie could get in the car. This made mom really upset and she got a migraine. Robbie was much better in the evening. He ate his dinner, was well behaved around his siblings, and got to watch TV for the last hour or so before bed. He went down rather easily with Andy sleeping in the same room.', 1780723452298, 'voice', 1780723452298, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('c97760c6-973c-4898-809b-b09b77a02979', 'profile-1780169301356', 1780599600000, 'Robbie had a good day, went to school, got dressed on his own, played soccer with dad, built blocks with his brother Andy, cleaned up his room, and took his medicine.', 1780599600000, 'voice', 1780708957301, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('0be35a3a-b1bc-4e56-a3ec-d67267b0a882', 'profile-1780169301356', 1780513200000, 'Robbie went to the zoo on a field trip and had a lot of fun. He had a nice dinner of salad and a hot dog and pushed his sister on the swing after dinner. He had his medicine before bed.', 1780513200000, 'voice', 1780710076632, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO diary_entries (id, child_profile_id, date, content, timestamp, source, created_at, synced) VALUES ('6c65a05e-c2f9-4e2a-ab50-bdc5cc6e4f3f', 'profile-1780169301356', 1780513200000, 'Robby got into a fight at school and was taken to the principal''s office. We were given a call by the principal afterwards and had a talk with Robby about the incident when we were having dinner.', 1780513200000, 'voice', 1780710228159, 0) ON CONFLICT (id) DO NOTHING;
