INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1782280830193', 'profile-1780169301356', '[{"role":"user","content":"What are his verbal strengths?","timestamp":"2026-06-24T06:06:50.961Z"},{"role":"assistant","content":"Robbie has several notable verbal strengths that shine through in various assessments and interactions. According to the neuropsychological evaluation conducted by Dr. Marilyn McCune, Robbie demonstrated a significant personal strength in verbal comprehension and reasoning abilities. He possesses an advanced vocabulary and a sophisticated collection of general knowledge, which allows him to easily grasp complex instructions and articulate his thoughts effectively.\n\nFor instance, during the Wechsler Intelligence Scale for Children (WISC-V) assessment, Robbie scored 124 on the Verbal Comprehension Index, placing him in the 95th percentile, indicating above-average abilities. Additionally, his expressive language skills were noted to be high, with scores indicating he is capable of engaging in imaginative play and demonstrating strong verbal affective tone.\n\nIn terms of storytelling, Robbie has shown remarkable creativity and detail. During the Clinical Evaluation of Language Fundamentals (CELF-5) assessment, he effectively communicated his thoughts and ideas, which reflects his high verbal abilities. His mother also noted that Robbie can be very kind and cooperative in one-on-one settings, showcasing his verbal strengths when he feels comfortable.\n\nOverall, Robbie''s verbal strengths are characterized by his advanced vocabulary, ability to comprehend and reason with language, and his creativity in storytelling, making him a bright and articulate communicator.","timestamp":"2026-06-24T06:07:08.287Z"}]'::jsonb, 1782280830193, 1782281228287, 1, 'What are his verbal strengths?') ON CONFLICT (id) DO NOTHING;
INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1782280747120', 'profile-1780169301356', '[{"role":"user","content":"What are his verbal strengths?","timestamp":"2026-06-24T06:00:12.588Z"},{"role":"assistant","content":"Robbie has several notable verbal strengths as highlighted in the evaluations. According to the neuropsychological assessment conducted by Dr. Marilyn McCune, his verbal comprehension and reasoning abilities are significant strengths. Specifically, he possesses an advanced vocabulary and a sophisticated collection of general knowledge, which enables him to understand and articulate complex instructions and nuanced concepts effectively.\n\nIn the Wechsler Intelligence Scale for Children (WISC-V) assessment, Robbie achieved a Verbal Comprehension Index (VCI) score of 124, placing him in the 95th percentile, indicating above-average abilities in this area. Additionally, his performance in the Vocabulary subtest also reflected high proficiency, with a scaled score of 14 (91st percentile).\n\nMoreover, Robbie''s expressive language skills are highlighted in the standardized measures, where he demonstrates high to very high proficiency in expressive language and pragmatic conversational skills. This suggests he is capable of engaging in imaginative play and storytelling, which aligns with his interests in comics and narratives.\n\nOverall, Robbie''s verbal strengths include advanced vocabulary, strong comprehension abilities, and proficiency in expressive language, which are critical for his communication and social interactions.","timestamp":"2026-06-24T06:00:25.014Z"}]'::jsonb, 1782280747120, 1782280825014, 0, 'What are his verbal strengths?') ON CONFLICT (id) DO NOTHING;
INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1782280658057', 'profile-1780169301356', '[{"role":"user","content":"What are his verbal strengths?","timestamp":"2026-06-24T05:58:47.908Z"},{"role":"assistant","content":"Robbie has several notable verbal strengths that have been highlighted in various assessments and observations. According to the neuropsychological evaluation conducted by Dr. Marilyn McCune, Robbie demonstrated advanced verbal comprehension and reasoning abilities, indicating he possesses a sophisticated vocabulary and a high-level ability to understand and reason with language. This was specifically noted in the evaluation conducted on October 25, November 1, 8, and December 14, 2025.\n\nAdditionally, during the Wechsler Intelligence Scale for Children (WISC-V) assessment, Robbie scored 124 on the Verbal Comprehension Index, placing him in the 95th percentile, which is classified as \"Above Average.\" His performance on subtests such as \"Similarities\" and \"Vocabulary\" also reflected high abilities, scoring 15 (95th percentile) and 14 (91st percentile) respectively.\n\nFurthermore, Robbie''s expressive language skills were noted to be very high, with both parent and teacher reports indicating he has strong verbal communication and pragmatic conversational skills. This is consistent with his ability to articulate his thoughts and ideas effectively, showcasing his creativity and imagination in storytelling, as observed by his mother and teachers.\n\nOverall, Robbie''s verbal strengths are characterized by his advanced vocabulary, strong comprehension skills, and ability to engage in imaginative and detailed storytelling, which are significant assets in his educational journey.","timestamp":"2026-06-24T05:58:53.304Z"}]'::jsonb, 1782280658057, 1782280733304, 0, 'What are his verbal strengths?') ON CONFLICT (id) DO NOTHING;
INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1782280418523', 'profile-1780169301356', '[{"role":"user","content":"What are his verbal strengths?","timestamp":"2026-06-24T05:57:16.676Z"},{"role":"assistant","content":"Robbie has demonstrated several verbal strengths, particularly in his verbal comprehension and reasoning abilities. According to the neuropsychological evaluation conducted by Dr. Marilyn McCune, Robbie possesses an advanced vocabulary and a sophisticated collection of general knowledge. He has shown a high-level ability to understand and reason with language, which is a significant personal strength (McCune Assessment, October 2025).\n\nAdditionally, during the Wechsler Intelligence Scale for Children (WISC-V), Robbie scored 124 on the Verbal Comprehension Index, placing him in the 95th percentile, indicating that his verbal skills are above average compared to his peers (McCune Assessment, October 2025). \n\nFurthermore, Robbie''s expressive language and pragmatic conversational skills are also reported to be high, as noted in the assessments completed by his mother and teachers. Both reports indicated high to very high proficiency in these areas, showcasing his ability to articulate his thoughts and engage in imaginative play effectively (McCune Assessment, October 2025). \n\nThese verbal strengths can be particularly beneficial for Robbie in navigating his social interactions and expressing his ideas, especially when he is engaged in topics of interest, such as drawing and storytelling.","timestamp":"2026-06-24T05:57:27.379Z"}]'::jsonb, 1782280418523, 1782280647379, 0, 'What are his verbal strengths?') ON CONFLICT (id) DO NOTHING;
INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1782280370179', 'profile-1780169301356', '[{"role":"user","content":"What are his verbal strengths?","timestamp":"2026-06-24T05:53:06.481Z"},{"role":"assistant","content":"Robbie has demonstrated several verbal strengths, particularly in his verbal comprehension and reasoning abilities. According to the evaluation conducted by Dr. Marilyn McCune, his verbal comprehension index (VCI) score was 124, which places him in the above-average range (95th percentile). This indicates that he possesses an advanced vocabulary and a sophisticated understanding of language.\n\nAdditionally, during his assessments, Robbie showed a strong ability to articulate his thoughts and ideas effectively. For instance, he was able to use complex sentences when making inferential statements about stories and demonstrated a high level of detail in his responses. In the \"The Crayons\" task, he was able to infer and explain the dynamics of the characters in a nuanced way, showcasing his ability to understand and convey complex ideas verbally.\n\nFurthermore, his performance on the Clinical Evaluation of Language Fundamentals (CELF-5) indicated that he has age-appropriate abilities in following directions, which is a critical aspect of verbal communication. His expressive language skills were also noted to be high, as he can communicate effectively in both structured and imaginative contexts.\n\nOverall, Robbie''s verbal strengths lie in his advanced verbal comprehension, expressive language abilities, and his capacity to engage in detailed storytelling, as highlighted in various assessments and observations throughout his evaluations.","timestamp":"2026-06-24T05:53:11.111Z"}]'::jsonb, 1782280370179, 1782280391111, 0, 'What are his verbal strengths?') ON CONFLICT (id) DO NOTHING;
INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1782280219573', 'profile-1780169301356', '[{"role":"user","content":"What are his verbal strengths?","timestamp":"2026-06-24T05:52:22.087Z"},{"role":"assistant","content":"Robbie has several notable verbal strengths that shine through in various assessments and observations. According to the neuropsychological evaluation conducted by Dr. Marilyn McCune in late 2025, Robbie demonstrated advanced verbal comprehension and reasoning abilities. His verbal skills are highlighted by a significant score of 124 on the Verbal Comprehension Index (VCI), which places him in the 95th percentile, indicating above-average capabilities in understanding and reasoning with language.\n\nAdditionally, during the assessment, Robbie exhibited an impressive vocabulary and a sophisticated grasp of general knowledge. His ability to articulate thoughts and ideas effectively was noted, allowing him to easily grasp complex instructions and understand nuanced concepts presented by teachers.\n\nIn the Clinical Evaluation of Language Fundamentals (CELF-5), Robbie scored within the average range for following directions, further showcasing his verbal processing abilities. His expressive language skills are also commendable, as he displays high proficiency in social communication, which is essential for effective interactions with peers and adults.\n\nOverall, Robbie''s verbal strengths include his advanced vocabulary, high-level reasoning skills, and ability to articulate ideas clearly, which were consistently observed in both educational settings and during assessments.","timestamp":"2026-06-24T05:52:27.235Z"}]'::jsonb, 1782280219573, 1782280347235, 0, 'What are his verbal strengths?') ON CONFLICT (id) DO NOTHING;
INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1782279459108', 'profile-1780169301356', '[{"role":"user","content":"What are his verbal strengths?","timestamp":"2026-06-24T05:49:50.218Z"},{"role":"assistant","content":"Robbie has several notable verbal strengths, as highlighted in the evaluations and assessments conducted. \n\n1. **Verbal Comprehension and Reasoning**: According to the Wechsler Intelligence Scale for Children (WISC-V) assessment, Robbie demonstrated a **Verbal Comprehension Index (VCI) score of 124**, which places him in the 95th percentile, indicating above-average verbal comprehension abilities. This suggests that he has a strong capacity to understand and reason with language.\n\n2. **Advanced Vocabulary**: Robbie possesses an advanced vocabulary and a sophisticated collection of general knowledge, allowing him to articulate his thoughts and ideas effectively. This is supported by his performance in the Clinical Evaluation of Language Fundamentals (CELF-5), where he showed age-appropriate skills in following directions and other language tasks.\n\n3. **Narrative Skills**: During the assessments, Robbie was able to engage in storytelling and demonstrated his ability to use complex sentences to convey ideas. For example, in the assessment of his storytelling skills, he was able to explain the story of \"The Crayons\" with rich detail and logical reasoning, showcasing his ability to infer and articulate narratives.\n\n4. **Expressive Language**: The Gilliam Autism Rating Scale (GARS-3) indicated that Robbie has high abilities in expressive language, which includes his capability to communicate effectively with others.\n\nThese strengths suggest that Robbie is not only articulate but also capable of engaging deeply with language, which can be a powerful tool for him as he navigates social interactions and academic challenges. Encouraging his verbal strengths through creative outlets like storytelling and drawing can further enhance his communication skills and emotional expression.","timestamp":"2026-06-24T05:49:56.291Z"}]'::jsonb, 1782279459108, 1782280196291, 0, 'What are his verbal strengths?') ON CONFLICT (id) DO NOTHING;
