INSERT INTO conversation_sessions (id, child_profile_id, turns, created_at, last_activity_at, archived, title) VALUES ('session-1780979716762', 'profile-1780169301356', '[{"role":"user","content":"Tell me about Robbie’s verbal abilities","timestamp":"2026-06-09T04:37:41.418Z"},{"role":"assistant","content":"I''m sorry, but the logged events do not contain specific information regarding Robbie''s verbal abilities. To better understand his communication skills, it might be helpful to log any instances where he expresses himself verbally, engages in conversation, or shares thoughts and feelings. This could include noting any conversations he has with family members, his responses during playdates, or any creative expressions like drawing or storytelling. If you have any specific examples or observations, feel free to share!","timestamp":"2026-06-09T04:37:44.159Z"}]'::jsonb, 1780979716762, 1780979864159, 0, NULL) ON CONFLICT (id) DO NOTHING;
